/* Real customer review data for 6 brand-new PetWise items (never crawled --
   no price/content/stock data exists for them, so they deliberately live
   outside the main catalog/REAL_* tables and are read by exactly one page:
   Ratings & Reviews > New Items, shown only when the selected company is
   PetWise. Source: a client-supplied review export (168 real reviews across
   6 ASINs). Sentiment is a genuine per-review read of the review text -- not
   inferred from the star rating alone (several 3-5 star reviews describe a
   pet that rejected or was lukewarm on the product, and are labeled neutral
   or negative to match; conversely a couple of lower-starred reviews whose
   own text is substantively positive are labeled positive). */
export interface PetwiseNewItemReview {
  id: number; asin: string; itemName: string; date: string; customerName: string;
  title: string; text: string; rating: number;
  sentiment: "positive" | "neutral" | "negative";
}

export const PETWISE_NEW_ITEM_REVIEWS: PetwiseNewItemReview[] = [
  { id: 0, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-01", customerName: "Carol202", title: "Very tough rawhide snack", text: "I dog sit occasionally for my sister's dog, Daisy, and I like to keep special treats around for her. She is very food-driven and giving her special treats reduces her separation anxiety. But I also don't want my sis to come back to a fat dog.\n\nI decided to try these Pet Factory Chip Dips Long Lasting Collagen Dog Chews Variety Pack, Flavor-Dipped Rawhide Treats on Daisy next time she comes to stay.\n\nThey are made with very tough beef rawhide so it should take her a while to work through one. I want to distract her when she gets anxious and starts watching out the window for my sis and if she likes these, they should do the trick.\n\nAlthough these are labeled as \"CHIP DIPS\" they are not crispy like potato chips. They feel stiff, but when I bent one it did not break.\n\nI can only guess at which color rawhide is what flavor. They all smelled pretty close to the same with my inefficient human nose.\n\nIf you have a dog that bulldozes through their treats, these are worth a try. It's a huge bag.", rating: 5, sentiment: "positive" },
  { id: 1, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "Amazon Customer", title: "Long chewing rawhide treats", text: "My dog sure seemed to enjoy these! The different flavors seem designed to appeal to humans more than anything else, but I'm not entirely sure how to tell which one is which since they're all mixed together inside the bag, even though they are different colors. I gave my 50 lb pit bull one of the lightest color ones and she ran off with it to her chewing spot and spent a goodly amount of time chewing on it, so these are longer chewing treats, which I appreciate. I'm not going to give them to her too often since they are made of rawhide, even though the listing claims it's some form of rawhide that's 25% easier to digest. I'm not sure how to validate that and I'm not going to test it out on my beloved pup, so these are a good once in a while treat for her.", rating: 5, sentiment: "positive" },
  { id: 2, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "CT in KS", title: "My dog is a fan, but I'm on the fence", text: "First, I love the fun variety of these collagen chews. The four flavors are great and my dog will pretty much eat anything, especially a treat. He took the chip and I noticed on the last part, he struggled to swallow. When the chewing is over, it doesn't really break down like a harder treat. They stay whole and are one step away from being rawhide which I don't allow my Lab to have. So, use at your discretion, maybe give in cut up bites. The chips don't have a noticeable aroma, except for the BBQ and it smells very meaty. Good product with a huge selection.", rating: 3, sentiment: "neutral" },
  { id: 3, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "Stephen", title: "My picky dogs both enjoyed these", text: "Who doesn\u2019t love a variety pack (or in this case a flavor bomb)? My dogs are spoiled and picky. I prefer to give them limited ingredient / naturally treats but they usually don\u2019t eat them. They both really liked these chips. Also, you get a large bag so it\u2019s a good value. I will buy these again for my dogs.", rating: 5, sentiment: "positive" },
  { id: 4, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "Amazon Customer", title: "Nice way to mix it up", text: "The variety pack is a great option if your dog gets bored eating the same thing every time. Mine happily worked through every flavor without picking favorites. The chews last a while, have a little flex instead of being rock hard, and didn't cause any stomach issues. Good quality, good value, and a nice way to keep treat time interesting.", rating: 5, sentiment: "positive" },
  { id: 5, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "TheDogsCar", title: "Messy, but Dogs Love Them", text: "I recently Rescued two Malamutes (Brother & Sister).\u00a0 The Male has a strong jaw, and the Female has sharp teeth.\u00a0 They both are aggressive chewers; in their own right.\u00a0 When I opened the bag, the Rawhide chips seemed pretty thin.\u00a0 I figured they would not last long.\u00a0 Turns out, they lasted longer than most.\u00a0 Kept them busy for a few minutes.\u00a0 The only downside, the Flavoring gets wet and then transfers onto things.\u00a0 They lick it up, but do not give these to a dog on a light fabric.\u00a0 Came in a good sized bag, and was full (see pic).\u00a0 Had an Airtight Seal, and a Ziplock strip; for resealing.\u00a0 They claim to be '25% Faster Digestion than Traditional Beef Hide', but the ingredients claim they are Beef Hide.\u00a0 Not sure what 'Digest-A-Boost' is?\u00a0 Only negative: it is a Variety Pack, and hard to tell which flavor is which?\u00a0 The Dogs like them all.\u00a0 So, no big deal.", rating: 5, sentiment: "positive" },
  { id: 6, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "The Review Desk", title: "Dog Chews", text: "My dog showed interest in these chews as soon as I opened the package, which doesn\u2019t always happen since she\u2019s usually pretty picky about treats. She happily chews on them until they\u2019re gone, and they\u2019ve quickly become one of her favorite rewards.Pros:* My dog really enjoys them and gets excited every time.* Keeps her occupied for a reasonable amount of time.* Easy to give as an occasional treat.* Doesn\u2019t create much of a mess.Cons:* I wish they were a little smaller my dog.* More expensive than some similar treats.Even though they\u2019re a bit pricey, they\u2019re one of the few chews my dog consistently looks forward to. Seeing how much she enjoys them makes them feel worth buying again, despite the higher price.", rating: 5, sentiment: "positive" },
  { id: 7, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-02", customerName: "Kat Reviews", title: "Huge Bag with Multiple Flavors", text: "I love that there are four different flavors of chews in one bag, and you get a huge bag! (16 oz.) I am a bit worried, however, that because all the flavors are in the same bag, the flavors might run together a bit.I think for the amount of chews you get in one bag and the quality of these chews, there is really good value here. Sadly, my Chihuahua did not like these at all! Our dog acted super excited when we opened the bag, but then was instantly disappointed by the treats inside. Our dog kept going up and smelling the dog chews we\u2019d place on the ground for him, licking them, and then walking away with no further interest. We tried to reintroduce these chews to him several times throughout the day, and we could not get him to actually try eating or chewing them, sadly. You can tell these are made very well and made of quality, beneficial ingredients like collagen, but sadly these just aren\u2019t for my dog.", rating: 3, sentiment: "neutral" },
  { id: 8, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-03", customerName: "michele", title: "The chews are a variety of flavors but are a bit hard to tell apart.", text: "Pet Factory Chip Dips Long Lasting Collagen Dog Chews Variety Pack, Flavor-Dipped Rawhide Treat for Aggressive Chewers, Peanut Butter, BBQ, Bacon & Chicken Flavors, 16 ozFirst impressions: Nice large bag with a resealable top filled with large pieces of dog chews. The chews are a variety of flavors but are a bit hard to tell apart. The dark ones are easy but the rest seem to be very like in color.Installation/setup: Give to your dog for a treat. Bag says to wash your hands after and not for human consumption.Final thoughts: I got this to treat my neighbor\u2019s dogs. I dogsit often and I like to give them treats. The pups are getting bigger now, and grabbed these quick to take outside in the run to chew lol. I treat them when they cooperate and go into their pen without complaints, just like their owners do. I like this and I\u2019m glad I got it.??1 star - I don't recommend it at all, poor quality.???? 2 stars - I don't recommend it, it has multiple faults, or a very high price.?????? 3 stars - It's passable, It has some faults but the quality is ok for what it is.???????? 4 stars - Product quite acceptable, it does what it promises.?????????? 5 stars - Product that I totally recommend.", rating: 5, sentiment: "positive" },
  { id: 9, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-03", customerName: "Baby Saja", title: "different flavors", text: "These are not my dog's first choice of treats, but she will chew on them.  One of the flavors she does not care for.  I couldn't tell you which one, I just see the color is different.She will eat all her other treats and come back to this one.  Then she chews it up.  It gives her some chewing time.Pet Factory Chip Dips Long Lasting Collagen Dog Chews Variety Pack, Flavor-Dipped Rawhide Treat for Aggressive Chewers, Peanut Butter, BBQ, Bacon & Chicken Flavors, 16 oz", rating: 4, sentiment: "neutral" },
  { id: 10, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-03", customerName: "Skyy Reviews", title: "Good Variety of Flavors", text: "Dogs seem to be enjoying these. The variety of flavors keeps things interesting, and they last much longer than many other treats we've tried. The flavor coating seems to make them extra appealing, and they keep my aggressive chewer busy for a good amount of time. A great option for dogs that enjoy chewing and a nice value for the variety pack.", rating: 5, sentiment: "positive" },
  { id: 11, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-03", customerName: "Amazon Customer", title: "My dog loves them!", text: "The bag is a lot bigger than I thought it would be, it looks small in the photos but it's a good sized bag. The pieces inside the bag are a mixture of 4 different flavors - peanut butter, bbq, bacon, and chicken. Some of the pieces are long and slim, like a strip, some are bigger and more of a square shape. None of them that I have chosen from the bag have been particularly thick. My dog has devoured every single one that I have given him so far, he really likes them. They are not \"rawhide\", they are beefhide, but that's not a whole lot different. My dog has not experienced and digestive or other issues after eating them. They are a bit messy, expect your dog's paws to be discolored after eating and you might want to have them eat them on an easily cleanable surface as the sauces and glazes will transfer to whatever surface they are being eaten on when the treats get wet from all the licking and chewing. They keep my dog busy and happy for several minutes. He loves them. The bag is decently priced, currently about $18. For the quality and quantity I think that's a good value. We would absolutely order them again in the future, and would recommend them!", rating: 5, sentiment: "positive" },
  { id: 12, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-03", customerName: "Brandee K.", title: "Great Variety Pack That Keeps My Dog Excited", text: "My dog absolutely loves these collagen chews. She gets excited every time I reach for the bag, and they have quickly become one of her favorite treats.One of the things I appreciate most is the variety of flavors. With peanut butter, BBQ, bacon, and chicken included, it keeps treat time interesting and helps prevent my dog from getting bored with the same flavor over and over, especially since the bag contains quite a few chews.The chews keep her occupied for a while, making them a great option when I want to give her something enjoyable to work on. I also like that they are collagen based rather than traditional rawhide.The resealable bag is convenient for storage, and the assortment makes it feel like you're getting several treats in one package.Overall, this is an excellent variety pack for dogs who enjoy long lasting chews. The different flavors keep things interesting, and my dog gives them an enthusiastic approval every time.", rating: 5, sentiment: "positive" },
  { id: 13, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-03", customerName: "Amazon Customer", title: "PUPS love these, but be careful with potential furniture or rug stains", text: "I have four aggressive chewers, so dog treats usually don't last very long around here. I handed one to each dog at the same time, and I was surprised by how long these lasted. Depending on the dog, they chewed on them anywhere from about 5 minutes to nearly 20 minutes, which is much longer than most treats survive in my house.\n\nThe bigger problem was making sure everyone kept their own treat! The fastest chewer finished first and immediately decided the slowest chewer's treat looked even better. I almost had to play referee before everyone finished.\n\nThis variety pack comes with four different flavors, and judging by my dogs' reactions, every flavor was a hit.\n\nThe one thing I do want to warn people about is that the darker-colored chews can stain. Two of the flavors left colored residue on my dogs' paws, and that color can easily transfer to rugs, furniture, or flooring. (See my photo.) Because of that, I highly recommend giving these as an outdoor treat or somewhere you don't mind getting a little messy.\n\nOther than the staining issue, these were a big success. My dogs loved them, they lasted longer than most chews we buy, and I'd definitely consider buying them again.", rating: 5, sentiment: "positive" },
  { id: 14, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-05", customerName: "CB", title: "Rawhide is Rawhide", text: "I like to start with the positives: This is an affordable treat option that dogs genuinely seem to enjoy. The flavor coating creates immediate interest, and the durable core keeps a dog occupied while offering a budget-friendly outlet for routine chewing.And while the brand leans on heavy marketing around \"collagen\" and proprietary terms like \"Digest-A-Boost\" (which lacks any clear, transparent information), these are, at the end of the day, ultimately just rawhide-based chews.Just so everyone knows, rawhide comes with well-documented risks\u2014including potential intestinal blockages, choking hazards, poor overall digestibility, and the harsh chemical processing typically used in manufacturing. Splitting marketing hairs doesn't change the underlying material.Pet owners should exercise caution, monitor their animals closely, and weigh the inherent risks before handing these over. We use them, but not often, and honestly, it is a wonder why these are still offered as a product type.", rating: 3, sentiment: "negative" },
  { id: 15, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-05", customerName: "AmazonCustomerCK", title: "Dogs loved them", text: "My dogs were excited about these chews from the moment I opened the bag and happily settled in to chew on them. They come in a nice variety of flavors and sizes, so there are plenty of options depending on your dog's preferences. I will say they were not as long lasting as advertised unless you consider about 45 minutes to be a long time. My dogs just sat there and gnawed on them until every bit was gone. One thing to keep in mind is that these are very tough, and you cannot easily break them into smaller pieces, so choose the right size if you have a smaller dog. They seemed to enjoy every minute of chewing, and I liked having something that kept them occupied for a while. I also appreciate that the price is priced appropriately for what you get. I'm rating this 5 stars because I would definitely get this again.", rating: 5, sentiment: "positive" },
  { id: 16, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-05", customerName: "Amazon Customer", title: "A nice variety of rawhide treats for dogs", text: "These chip dip chews from Pet Factory are a HUGE hit for my dog. I like that this is a variety pack, so it comes with cheddar bacon blast, backyard bbq, peanut butter crunch, and chicken 'n waffles. Honestly the flavors can be a little hard to distinguish from each other, but that's not really a big deal since my dog loves all the flavors equally lol.The ingredients to these seem to be pretty good. As with all rawhide products, it's a good idea to keep an eye on your dog as they're chewing to avoid them swallowing large chunks or choking, but so far my dog has been fine with eating these. These are collagen based, so they're more digestable and less likely to cause blockages than traditional rawhide is, which is nice.My dog absolutely loves them and they're a great way to keep her busy and distracted for a bit. The chews themselves are small to medium sized, so it doesn't take her that long to get through one, but they're good for a nice 10-15 minute distraction. They're great for an occasional treat as a reward as well. The bag is huge, and since she's just one little dog, one bag will last us a while before we'd need more, so they feel like a great value.", rating: 5, sentiment: "positive" },
  { id: 17, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-06", customerName: "Amazon Customer", title: "Long-lasting treat that keeps dogs busy with a flavor they love", text: "My dogs absolutely love these chews! They take quite a while to finish just one, which is a huge plus because it keeps them entertained and occupied for a good stretch of time.?The flavors are clearly very savory because my dogs go crazy for them and truly enjoy every bite. It is a great option for heavy chewers who need something to work on.?The only downside is that as the chew gets soggy while they work on it, they tend to hold it down with their paws. This leaves the fur on their paws pretty sticky afterward, so you might need to wipe them down when they finish.?Overall, if you are looking for a long-lasting, flavor-packed treat that keeps your dogs busy, these are definitely worth picking up!", rating: 5, sentiment: "positive" },
  { id: 18, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-07", customerName: "Amazon Customer", title: "No kcal listed, hard to know how often small dogs can eat one.", text: "I thought my dog would love these, but she isn't the biggest fan so far. I do still have faith that she'll eat it. She only likes to eat it if my partner and I are in the same room. She loves cheese and bacon and that is the flavor I think I gave to her first. So far this is just a burry bone. Hopefully she will end up eating it.I hate when they have the analysis, but don't list what the kcal is for each piece. It doesn't look like it would be that much, but my dog is 15lb so it really makes a difference on if it's 30kcal vs 110kcal. I would have to give her slightly less food for the day if it was the latter.It is a huge bag. If you don't have a picky dog or aren't worried about kcal then these will be great for your dog!", rating: 5, sentiment: "neutral" },
  { id: 19, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-07", customerName: "Akdre", title: "Rawhide, not collagen chews. Misleading product title", text: "I purchased these thinking they were collagen chews, but after they arrived I realized they\u2019re actually rawhide chips coated with collagen. That was disappointing, as I avoid giving my dogs rawhide because of its heavy processing and potential digestibility concerns. I ended up donating the bag instead of feeding it to my dogs.That said, the chips are a nice snack size, and I like that they come in a variety of flavors. If you\u2019re comfortable giving your dogs rawhide, these may be a good option. They just weren\u2019t the right fit for my household, so be sure to read the product description carefully before purchasing.", rating: 4, sentiment: "negative" },
  { id: 20, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-07", customerName: "Reeseview", title: "High-protein, long-lasting collagen chews in bold, snack-inspired flavors", text: "The Pet Factory Chip Dips Collagen Dog Chews Variety Pack offers a rewarding and durable solution for dogs with strong chewing instincts. The primary functionality of these treats combines a long-lasting collagen chew core with flavorful, snack-inspired coatings like Peanut Butter Crunch, Cheddar Bacon Blast, Backyard BBQ, and Chicken 'N Waffles. This design is intended to turn routine chew time into an engaging and tasty experience that helps satisfy a dog's natural desire to chew while providing helpful enrichment.The quality of the product is centered on its collagen-based formula, which is designed to be easier to digest than traditional rawhide alternatives. The inclusion of the DIGEST-A-BOOST ingredient reflects a focus on digestive wellness, making these chews a practical choice for daily enjoyment. Beyond the taste, the high-protein collagen core supports healthy joints and mobility, and the durable texture provides a mechanical cleaning action that assists in supporting healthy teeth and gums.In terms of usability, these chews are made in the USA and cater to a wide range of dogs, with owners of large, powerful breeds noting their durability during focused chew sessions. They offer a manageable and relatively clean treat option that keeps dogs occupied for significant periods without being overly filling or high in unwanted fats. This variety pack is a convenient way to keep your dog's treat routine exciting while maintaining a focus on high-quality, protein-rich ingredients that pet parents can feel confident about.", rating: 5, sentiment: "positive" },
  { id: 21, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-08", customerName: "amy", title: "12 paws up from our 3 fur babies", text: "My dogs go CRAZY for these. They don't upset their stomachs, They chew them up well so I don't worry about the pieces breaking off when they're too big. There's two kinds in the bag and one is darker than the other. The only complaint I have its the color from the dark ones transfers to my white dog's paws and outer mouth area. To be expected, but just be careful not to give those to a dog while it's laying on your light colored furniture or carpet. Love the ingredients, digestability and longevity!", rating: 5, sentiment: "positive" },
  { id: 22, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-09", customerName: "Amazon Customer", title: "Chew-tastic Surprise for My Gnawing Pup", text: "I tried these chews with my lab, and they lasted much longer than the rawhide he usually tears through. He seemed to really like the peanut butter and bacon flavors and actually slowed down while chewing. I also noticed his breath seemed fresher after a few days. A few pieces flaked off and made a small mess, but overall they held up well and kept him busy much longer than his usual chews.", rating: 5, sentiment: "positive" },
  { id: 23, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-09", customerName: "Amazon Customer", title: "Highly engaging, protein-packed chew treat!", text: "These Pet Factory Collagen Dog Chews are a massive hit around our farm! Because they\u2019re packed with natural collagen, they offer a great protein boost while keeping my dogs happily occupied for a solid chunk of time.The variety of flavors\u2014like peanut butter, BBQ, bacon, and chicken\u2014means there\u2019s always something new and exciting to keep them motivated. I really appreciate that the formula is highly digestible and free of common fillers like corn or gluten, making them feel like a much healthier, safer alternative to traditional rawhide treats. They\u2019re a fantastic, durable option for keeping active dogs entertained and satisfied!", rating: 5, sentiment: "positive" },
  { id: 24, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-18", customerName: "Mandy", title: "Dogs Love the Variety", text: "My dog really enjoys these chews, and the variety of flavors is a nice touch. They keep her occupied for quite a while and seem to be easier on her stomach than some other long-lasting chews we\u2019ve tried. The different flavors make it easy to switch things up. My only complaint is that some pieces seem to be chewed through faster than others, so they aren\u2019t always as long-lasting as advertised. Overall, a good variety pack for dogs that enjoy chewing.", rating: 4, sentiment: "positive" },
  { id: 25, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-08-20", customerName: "Amazon Customer", title: "Pet Factory Chip Dips collagen dog chews variety pack", text: "I ordered this because my neighbor's dog was going absolutely feral on her furniture and she asked me to grab something for him while I was doing my online shopping, so here I am reviewing dog treats despite owning a cat who would sooner bite me than accept a collagen chew. The bag is a decent size and the individual chews are strip shaped and fairly rigid with a slightly waxy coating on the outside that you can actually see and smell. The four flavors in the variety pack are peanut butter crunch, cheddar bacon blast, backyard BBQ, and chicken and waffles and honestly the bacon one smells strong enough that my cat came to investigate.\n\nHer dog is a big lab mix and he is what I would generously call an enthusiastic chewer. He goes through most treats in under two minutes but these take him a while and he stays focused on them without wandering off looking for something else to destroy. The collagen core is denser than a standard rawhide and holds up better under sustained chewing pressure. He has not had any digestive issues with them and she has been giving them to him regularly for a few weeks now.\n\nThe variety pack format is nice because some flavors hold his attention longer than others and the peanut butter one seems to be the last one he finishes.", rating: 5, sentiment: "positive" },
  { id: 26, asin: "B0H5FVF31S", itemName: "Chip Dip Variety Pack", date: "2026-09-05", customerName: "Donna McCormick", title: "Not happy with product. Wasted money \ud83e\udd11", text: "Neither of my two dogs liked any of the four flavors. They will not try to chew on them at all.", rating: 1, sentiment: "negative" },
  { id: 27, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-02", customerName: "Amazon Customer", title: "Another Flavor My Dog Really Enjoys", text: "I decided to try the Backyard BBQ flavor after having good luck with the other variety, and my dog loves these just as much. They last a long time compared to most treats and keep my dog occupied without disappearing in a few minutes. The collagen material seems durable while still being easier to digest than traditional rawhide products. I also like that they don't leave a huge mess around the house after chewing. The quality has been consistent from one chew to the next, and the bag offers a good amount for the price. Overall, these have become one of my dog's favorite treats.", rating: 5, sentiment: "positive" },
  { id: 28, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-02", customerName: "Amazon Customer", title: "Good ingredients and longevity, but not lighting my dog's world on fire", text: "I picked up these long-lasting rawhide dog chews in the backyard BBQ flavor, and while the flavor sounds like it would be a hit, my dog was pretty indifferent to them. The chews have a smoky smell to me, which is probably meant to resemble the BBQ flavor, but my dog did not seem as excited about them as he is with some other treats. He did try one and chewed on it for a bit, but he wasn\u2019t rushing back for more.The bag comes with a good amount of chews, so there is plenty to keep on hand. I also noticed that the odor is much milder compared to other rawhide treats I\u2019ve purchased, which is a nice plus. My dog was able to digest the chew without any tummy issues, but I have not used them long enough to notice any changes in his coat, joints, or dental health.The product seems decent, and my dog was able to enjoy one, but the backyard BBQ flavor just wasn\u2019t his favorite.", rating: 4, sentiment: "neutral" },
  { id: 29, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-02", customerName: "Kristi Martin", title: "So messy!", text: "My dog loves these Pet Factory Chip Dips Long Lasting Collagen Dog Chews for Aggressive Chewers, Easy to Digest Rawhide Dog Treats with Digest-A-Boost\u00ae, Flavor-Dipped Backyard BBQ Dog Chews, 16oz I appreciate that they are collagen chips which are preferable over many other dog treats and that these are made so they are easy to digest. The chips are thin and flat making them easy for my dog to chew on and hold onto with her paws. However, the coating which is a reddish color, does state in small print in the product description, can transfer, makes a huge mess. Not only did the coating get all over the carpet but was all over her face and paws and I had to spot clean the carpet and use a wipe to clean it from her face and paws. I would not recommend these for a white dog or really any dog if you don\u2019t want the mess left behind. It is a shame, as these collagen chips come in a variety of flavors which I know my girl would enjoy but the mess isn\u2019t worth it to me. I did find that I could rinse off most of the outer dip coating which makes them less messy, but I am sure it also makes them less tasty to my dog and defeats the purpose of the flavor-dipped feature of these chews.", rating: 3, sentiment: "negative" },
  { id: 30, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-02", customerName: "Amazon Customer", title: "Great for dental health", text: "I\u2019m always cautious when I try new treats with my dog. He\u2019s picky about flavor and texture and usually prefers protein\u2011based treats. I didn't know exactly what to expect from the flavor Backyard BBQ. Would it be smoky, beefy,  or have a BBQ flavor like potato chips? The answer is that it is smoky, which is apparent as soon as the bag is opened. I wondered if he would reject it, but he didn't even hesitate. He settled in and chewed steadily until the entire chew was gone. It kept him occupied for a good stretch of time, which is exactly what I look for in a dental chew. Because his teeth weren\u2019t in great shape when we first adopted him, I\u2019ve made it a point to order treats and chews that address dental health. Since he likes these so much, my intention is to offer him one daily to help keep his teeth and gums in better condition. The hard texture gives him something to really work on. He clearly enjoys the chewing as much as the flavor. The bag includes an important warning: the coatings are water\u2011soluble and the color can transfer. They aren't exaggerating. My dog is solid white, so I can see that a lot of color transfers to his fur. I treat these as outdoor\u2011only chews in order to protect my home from stains. I want to point out that the ingredients on the listing page don\u2019t match the ingredient list on the bag. The actual ingredients printed on the package are: beefhide, maltodextrin, natural beef flavor, natural smoke flavor, brewer\u2019s dried yeast, caramel (color), guar gum, and salt. The chews are made in the USA, which makes me feel more comfortable about the sourcing and manufacturing. The expiration date on my bag is 36 months in the future, so there\u2019s plenty of time to use them up. The large 16 ounce bag holds a ton of chews. The current price of $17.97 is reasonable for how many chews you get and how long each one lasts. Backyard BBQ turned out to be a hit with my dog, despite my initial doubts about the flavor. As long as we stick to using them outside to avoid color transfer, they\u2019re a nice addition.", rating: 5, sentiment: "positive" },
  { id: 31, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-03", customerName: "yetanothereviewer", title: "Dogs love them, made in the USA", text: "My dogs are so happy I got these.  They're pretty serious chewers, so I love it when I can find good treats for them that last more than five seconds.  These are good sized beef hide pieces that keep them busily chewing for several minutes.  They love the flavor, too.  One of my dogs is a little pickier than the other, but he didn't hesitate when I handed this to him.  Both of my dogs grabbed these and ran off like they had just robbed a bank.I don't often give them beef hide treats because it can upset some dogs' tummies.  These pieces aren't as big as a giant rawhide bone, so that helps.  Also there's apparently something they do to these that's supposed to make them a little more digestible than regular rawhide.  I dunno, but I can tell you that neither of these guys seemed to have any trouble with them.These are actually made in the USA, which is one of the first things I look for.  I feel like a U.S. manufacturer is less likely to contaminate dog treats with bad things.  This company has been making dog treats in a factory in Illinois since 1989, so that's reassuring.This is a huge bag of treats for only $18, which seems like a really good deal.  The bag is a pound, which may not seem like a lot, but rawhide is pretty lightweight, so it's a big bag.  I weighed the bag and it came in at just over 1 lb.", rating: 5, sentiment: "positive" },
  { id: 32, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-03", customerName: "Amazon customer", title: "Thin , better for smaller dogs", text: "Personally my dog is not a big fan due to his size and bite \u2026 they are not flimsy but they are very thin . I find these to be good for gentler or smaller dogs.The Barbecue sauce is lightly spreading onto the treat providing bursts of flavor !Great choice for a gentle pet that likes to chew", rating: 4, sentiment: "neutral" },
  { id: 33, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-03", customerName: "Amazon Customer", title: "dogs are ok with these", text: "I bought these Pet Factory Chip Dips in the Backyard BBQ flavor for my two dogs, a 30-35 lb mix breed and an American Eskimo of the same size. Both were pretty neutral about them at first. They chewed on one for a bit but did not get as excited as they do with some of their usual favorites. The smoky smell is noticeable to me but milder than other rawhide treats I have tried, which is a nice change.The 16 oz bag has a good number of chews, so it feels like solid value. My dogs finished theirs in a few minutes and digested them fine with no stomach issues or weird behavior afterward. I always supervise them while they chew just to be safe.Overall these seem like a decent option if your dog is not super picky. They keep my pair occupied for a short while without the strong odor some other chews have, though they are not the longest lasting treats we have used.", rating: 5, sentiment: "neutral" },
  { id: 34, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-03", customerName: "A.Lamb", title: "My Dogs Lose Their Minds Over These", text: "My dogs go absolutely bonkers for these. I have an older doxle and a middle aged red coonhound Lab mix, and neither one of them has any act right when I open this bag or even move toward it. These had only been in my home for about 48 hours before they both knew exactly what the bag was, so right off the rip I would recommend them. Do I know what benefits my dogs are going to receive from them yet? No, but I do know that I have an aggressive chewer and one strip takes her around 10 to 15 minutes to completely annihilate, which lasts longer than almost every other treat I have given her outside of large bones. I expected the bag to be much smaller, so I was over the moon when I saw how much product was actually included because it makes the price point completely worth it. The strips are a little smaller than I would prefer for my larger dog, but they still work perfectly for her and that is only a personal preference that does not affect the product. The texture reminds me of pig ears, and I am already planning to order the other flavors because if she loves the backyard barbecue this much, I know she is going to lose her mind over the peanut butter ones.", rating: 5, sentiment: "positive" },
  { id: 35, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-03", customerName: "Wendy/The Thrifty Sewist", title: "Dog approved", text: "I was pleasantly surprised when this bag of treats arrived. It\u2019s much bigger than I anticipated. The treats are a nice, large size as well. They are a longer lasting chew which I like because it occupies my dog for quite a while. I have a 13 pound Pomeranian and she absolutely loves these. It probably takes her close to an hour to finish one of these. I also love that they are made in the USA. Overall, highly recommend!", rating: 5, sentiment: "positive" },
  { id: 36, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-04", customerName: "Me", title: "Great for keeping dogs busy but best given outdoors", text: "Pros:* Smoky aroma that dogs seem to love immediately* Keeps dogs occupied for a good amount of time* Generous bag size with plenty of chews included* Great texture for satisfying natural chewing instinctsCons:* Colored coating transfers easily onto dog fur and indoor surfaces* Strong smoky scent might be intense for some ownersFinding chews that keep a dog busy without disappearing in two minutes can be a challenge. These barbecue flavored collagen chews have been a solid addition to our routine. Right when you open the bag, there is a very distinct smoky scent that immediately caught my dog's attention. He did not hesitate at all and went straight to work on one, settling down on his mat and chewing steadily for a solid stretch of time.The chews have a flat design that makes them easy for a dog to hold between their paws. The outer coating seems to carry most of the flavor, while the collagen core gives them enough durability to last through an extended chewing session.The main thing to keep in mind is the outer flavor dip. The reddish coating dissolves as the dog chews, which means it can transfer color onto carpet, couch fabric, or even light colored fur around your dog's mouth and paws. To avoid any potential mess on rugs, we turned these into outdoor only treats or gave them while he was on an easy to wipe floor. As long as you plan around the potential color transfer, these offer great entertainment value and a very satisfying chew for dogs.", rating: 4, sentiment: "positive" },
  { id: 37, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-04", customerName: "Amazon Customer", title: "BBQ disappeared fast", text: "The BBQ flavor was definitely a hit. My dog carried it around for a minute like it was treasure. Then she settled into licking it for a good 20 minutes before getting down to business. The chew has just enough give to it while still lasting a long time. No stomach issues afterward, and it kept her occupied much longer than most treats. I'd get this flavor again. I didn't smell awful and it didn't leave a mess, though I do make her chew it on her bed.", rating: 5, sentiment: "positive" },
  { id: 38, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-04", customerName: "C\u00e1it", title: "\u2728\ud83c\udf56 my dog believes all furniture should be seasoned \ud83c\udf56\u2728", text: "i keep making the same mistake. i assume the dog will *simply* eat the treat. the dog assumes we are marinating the living room. she absolutely adores these barbecue collagen chews. the second one appears, she takes it with the solemn urgency of someone accepting a classified document and disappears to wherever she has decided the chew should be dealt with privately.they actually last too, which i appreciate. \u201clong-lasting\u201d is one of those phrases dog treat companies use with tremendous optimism. some chews survive four minutes and a determined expression. these keep her occupied for a proper stretch.the barbecue coating does transfer while it is still on the chew.this is standard flavoured dog treat behaviour.i included a photo so you know what to expect, not because i think it is a flaw.ask me about the christmas bones of years past that left festive red and green stains all over my cream fluffy blanket because somebody decided it was the ideal place to bury them.i have lived.compared with those, this is practically restrained.once the coating has been licked or chewed off, it stops transferring. and if your dog does briefly decide the rug requires seasoning, a little dawn dish soap and water on a cloth took it straight off for me.no stain.no funeral for the furnishings.just another normal evening in a home where the dog has opinions about flavour placement.at $17.97, these are just under two chais in new york, where a chai costs roughly $10 because cinnamon has apparently joined the luxury goods market. if you\u2019re new to my reviews, chai is currency. these earn theirs. my dog loves them, they last well, and i already know exactly where not to let her bury one.\u2728tl;dr\u2728 excellent long-lasting barbecue collagen chews that my dog is fully committed to. the coating transfers at first, as flavoured dog treats tend to do, then stops once licked off. any residue cleaned up easily, and the christmas blanket has seen far worse.", rating: 5, sentiment: "positive" },
  { id: 39, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-04", customerName: "Amazon Customer", title: "My dogs are a fan", text: "The dogs love these chews when I offer them.  They are kept occupied chewing for 15 minutes or so.  They've eaten the entire chew and haven't suffered any digestion issues.  They seem to really enjoy the taste and of course, chewing on the treats.  Sometimes they eat the entire thing and other times, leave a little bit but they always are happy to get them.  I'm happy to give them these treats as they're made in the USA and I think they're priced well.  Very happy with these treats.", rating: 5, sentiment: "positive" },
  { id: 40, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-04", customerName: "Mom next door", title: "Flavorful collagen chews with a satisfying texture", text: "These chews have a strong backyard barbecue scent and a textured coating that makes them more interesting than plain dog chews. The pieces vary in size and shape, so they are easy to choose based on how large of a treat you want to give.I like that they are made with a collagen-based core rather than traditional rawhide and are designed to be easier to digest. They also take longer to work through than an ordinary soft treat, which can help keep a dog occupied for a while. The resealable 16-ounce bag is a generous size and keeps the remaining chews fresh.", rating: 5, sentiment: "positive" },
  { id: 41, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-05", customerName: "Stephen", title: "Good value for the money!", text: "My dogs both liked them! Also, it\u2019s a big bag which is nice.", rating: 5, sentiment: "positive" },
  { id: 42, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-06", customerName: "Amazon Customer", title: "Long-lasting treat that keeps dogs busy with a flavor they love", text: "My dogs absolutely love these chews! They take quite a while to finish just one, which is a huge plus because it keeps them entertained and occupied for a good stretch of time.\u200bThe Backyard BBQ flavor is clearly very savory because my dogs go crazy for them and truly enjoy every bite. It is a great option for heavy chewers who need something to work on.\u200bThe only downside is that as the chew gets soggy while they work on it, they tend to hold it down with their paws. This leaves the fur on their paws pretty sticky afterward, so you might need to wipe them down when they finish.\u200bOverall, if you are looking for a long-lasting, flavor-packed treat that keeps your dogs busy, these are definitely worth picking up!", rating: 4, sentiment: "positive" },
  { id: 43, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-06", customerName: "MT2", title: "My other adopted dog loved these", text: "I took this bag to my other adopted dog, my client's dog who always waits for me at the door so excited for the snacks I bring her. She was so happy with the size and the taste of these, she went crazy for them. The treats are big and seem to last a while, which is good because she chews on them for a long time. Hopefully they will last since it is a big bag, but with how much she loves them, I might need to get more soon. Definitely a hit with her.", rating: 5, sentiment: "positive" },
  { id: 44, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-06", customerName: "Amazon Customer", title: "Packed with flavor, durable and long lasting chewing experience, natural ingredients", text: "These large sized dog chewable treats are naturally delicious for dogs and my dogs love them. The aroma is strong and enticing and the treats are durable and long lasting even for heavy chewers. The barbecue flavor is irresistible and encourages safe and healthy chewing habits. The quality is superior to other chew treats we have used before. The large pieces offer variety in shape due to the natural preparation process, which keeps it interesting for dogs to chew on. I like that the pouch is resealable to keep contents at peak freshness and keep moisture out, while keeping the strong aroma from escaping, once you open these the smell will quickly fill the room and if you have a sensitive nose you will want to close it as soon as possible again. Long lasting chewing fun and tasty real flavor, natural ingredients I can trust and a good value for this long lasting amount of treats per pouch. Highly recommend these!", rating: 5, sentiment: "positive" },
  { id: 45, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-08", customerName: "Mimi", title: "can I say yum? my dog sure does", text: "These treats were an instant hit with my dog. As soon as I opened the bag, the excitement started, and the Backyard BBQ flavor seems to be a winner. Can I say yum? Haha. My dog certainly would if she could. The chews keep her busy for a while and satisfies her need to chew.I also like that they are collagen based and easy to digest. The pieces are a good size, and the 16 oz bag gives you plenty to work with. The price is fair for such a big bag, and most importantly, my dog absolutely loves them.", rating: 5, sentiment: "positive" },
  { id: 46, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-08", customerName: "Coffee & Feathers", title: "My aggressive chewers found their favorite new treat!", text: "Both of my large breed pups are aggressive chewers, and they are absolutely obsessed with these backyard bbq \u201cchips\u201d! One piece keeps them occupied for quite a while, which is impressive with my dogs.These are made from beefhide as a source of collagen, so I definitely supervise while my dogs are chewing them. As you can see in my photos, they soften and get thinner as they\u2019re chewed. Once a piece gets small enough that I\u2019m concerned they could swallow it whole, I take it away.You get a surprisingly generous amount in the 16 oz bag. At $17.97 at the time of my review, I think these are an excellent value, especially considering how much enjoyment my dogs get out of them.My Smokey and Charlie Ann LOVE these, and we are definitely ordering more!", rating: 5, sentiment: "positive" },
  { id: 47, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-09", customerName: "Amazon Customer", title: "Backyard BBQ Chew: My Dog's New Favorite Snack (and Mine?)", text: "I gave these Backyard BBQ Chip Dips to my 7-year-old Lab, and he took to them right away. He spent much longer chewing on them than the rawhide sticks I usually buy, so I wasn\u2019t throwing away a half-eaten treat after a few minutes. The smoky, slightly sweet smell definitely kept his attention. After a week, his teeth and gums have looked a little cleaner to me, although I can\u2019t say how much of that was from the chews. He also seemed fine after longer walks, and I didn\u2019t notice any digestive issues. The main downside is the BBQ smell, which lingers in the kitchen for a while after opening the bag. Still, they\u2019ve kept him occupied longer than most of the chews I\u2019ve tried.", rating: 5, sentiment: "positive" },
  { id: 48, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-10", customerName: "Reviewer", title: "Collagen Dog Chews", text: "These Backyard BBQ collagen chews were another big hit with my dog. He was immediately interested in them, and the BBQ flavor seems to make them especially appealing.I really like the chip-style shape because the pieces are easy to portion and provide a satisfying chew without being as large or cumbersome as a traditional long chew. They keep my dog occupied much longer than an ordinary treat.The 16-ounce bag contains a generous amount, and the pieces have a nice firm texture for dogs that really enjoy chewing.As with any chew, I supervise my dog while he's eating one and remove any remaining piece if it gets small enough to potentially be swallowed whole.Overall, my dog thoroughly enjoys these, and I like having an easy-to-portion treat that gives him something to work on for a while. The Backyard BBQ flavor definitely gets his approval! \u2b50\u2b50\u2b50\u2b50\u2b50", rating: 5, sentiment: "positive" },
  { id: 49, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-10", customerName: "Amazon Customer", title: "Pet Factory Chip Dips Collagen Dog Chews (Backyard BBQ)", text: "These Pet Factory Chip Dips collagen chews have been a solid treat for my dog. The Backyard BBQ flavor is a clear favorite \u2014 he goes for them eagerly every time. At 16 oz, the bag lasts a good while, and the chews are thick enough to keep an aggressive chewer occupied for a decent stretch.After two weeks of regular use, they\u2019ve held up well without breaking apart too quickly. The texture is firm but not overly hard, and the flavor coating seems to keep him interested longer.They\u2019re a practical option for keeping him busy and satisfied. The size and durability make them useful for both daily chews and longer sessions. Overall, a reliable and enjoyable treat that delivers on lasting power and taste. Very happy with them.", rating: 5, sentiment: "positive" },
  { id: 50, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-11", customerName: "Celina", title: "My Dog Goes Crazy for These!", text: "My dog absolutely loves these chews! The Backyard BBQ flavor seems to be a huge hit, and he gets excited as soon as he sees me grab one. The flavor coating definitely makes these more appealing to him, and they keep him busy for a good amount of time.I have a pretty aggressive chewer, so I really like that these don't disappear immediately. They hold up well and give him something to work on when he needs to stay occupied.I also like that they're collagen chews and are easy to digest compared to some of the other options we've tried. The 16 oz bag gives us plenty to keep on hand, too.These have quickly become one of his favorite treats, and I'll definitely be buying them again!", rating: 5, sentiment: "positive" },
  { id: 51, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-17", customerName: "3 Generations", title: "Harley loves them!", text: "The Pet Factory Chip Dips Dog Treats work well for Harley. I wouldn\u2019t call her an aggressive chewer, but she has been through dozens of toys. She\u2019s more persistent than anything, and these are easy for her to digest.I have both flavors Cheddar Bacon Blast and Backyard BBQ. She loves both of them but actually leans to the cheddar bacon one more. They keep her busy and out of trouble, and I like that they\u2019re natural treats. The chews last her a good amount of time, and she gets excited every time I open the bag. It\u2019s a huge 16oz resealable bag to keep moisture out and will last us quite some time, especially since she gets these as her \u201cstay busy\u201d treats. The treats don't have any weird smell and actually have a nice crunch texture to them.", rating: 5, sentiment: "positive" },
  { id: 52, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-20", customerName: "Amazon Customer", title: "Pet Factory Chip Dips Backyard BBQ collagen dog chews", text: "I ordered this because my neighbor's dog goes absolutely feral for rawhide chews and I wanted to grab something as a treat for her when she visits, but then I figured I might as well see what the fuss is about since my cat obviously has zero interest. The strips are flat and kind of chip shaped which makes sense given the name and they have a visible coating on the outside that smells genuinely smoky and sweet in a backyard cookout sort of way. The bag is a solid 16 ounces so there are quite a few pieces in there and the collagen core feels dense and a little rubbery when I press on it.\n\nWhen the dog visits she gets one of these and she is not subtle about it. She takes it to the corner of the room and works on it for a long stretch of time without losing interest and without shredding it into a million pieces all over my floor the way she does with some other chews. The coating does come off as she chews and there are faint smear marks on my hardwood but nothing that does not wipe up. She is a medium sized dog and a determined chewer and the chew holds up longer than I thought it would.\n\nThe Digest A Boost thing is printed pretty prominently on the front of the bag and I have no way to evaluate what that means in practice. What I can say is that she finishes one and then goes and drinks water and seems satisfied and calm afterward.", rating: 5, sentiment: "positive" },
  { id: 53, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-08-22", customerName: "AliasSmithNJones", title: "Good chews for dogs", text: "This is a 16 oz resealable zip top bag of Chip Dips in Backyard BBQ flavor, from Pet Factory. It arrived fresh and factory sealed. These are rawhide type chew treats for dogs, coated with a BBQ flavoring. They have a high protein content and are a healthy treat. I can't personally speak to whether the BBQ flavor is good, but I will say that dogs love these treats! Although rawhide type treats sometimes have a bit of a bad rep for digestibility, these are treated with enzymes to help improve digestion. These are chips, and are in a variety of sizes. They are suitable for most sizes of dog. At the current price of $17.97 for the 1 lb bag, I think these are a good value.", rating: 5, sentiment: "positive" },
  { id: 54, asin: "B0H4S8Z4XJ", itemName: "Chip Dip BBQ", date: "2026-09-08", customerName: "A", title: "My dog loves it but it\u2019s tough. Leaves a bit of a mess behind.", text: "Should've paid more attention to the \"for aggressive chewers\" part. I got it thinking it'd be like a chip that you can snap and break into smaller pieces and give to your dog, but no. Even with the sharpest pair of kitchen shears these are impossible to cut, break, or tear into smaller pieces. It's basically a flat, unfurled version of those no hide collagen rolls. My dog seems to love it and it does keep her occupied for a very long time, espeically since she is a senior dog who's had 8 teeth pulled. The bbq sauce seasoning on the chips does leave a dark brown mess behind though, and it stained my dog's white bed. I definitely have to watch over my dog like a hawk and make sure she doesn't eat it on the couch or my white rug.", rating: 4, sentiment: "neutral" },
  { id: 55, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-02", customerName: "Amazon Customer", title: "Chew kept him busy for a while", text: "I have a fifty\u2011pound dog who is extremely picky about treats. He usually only accepts protein\u2011based treats, but he loves to chew, so I decided to give these Pet Factory Chip Dips a try. Since he\u2019s a fan of both cheese and bacon, the Cheddar Bacon Blast flavor felt like the flavor with the greatest chance of success. His reaction was hilarious at first. I handed him a chew, and he just stared at it like he had no idea what it was. He dropped it on the floor, looked at me, and waited. I handed it back, and we repeated that cycle a few times. Eventually, the flavor must have caught his attention because he finally started chewing. Once he committed, he didn\u2019t stop until it was completely gone. It took him quite a while to finish, which I appreciate because he needs long\u2011lasting chews to help clean his teeth. When he first came to us as an adult dog, the vet told me his teeth would need a cleaning soon, so I\u2019ve made it a priority to find chews and treats that support dental health. My plan is to give him one Chip Dip daily to help keep his teeth in better shape. He clearly enjoyed the flavor and the chewing experience, but I did run into one issue. My dog is solid white, and when he finished his chew, his paws and the sides of his mouth were yellow. Then I looked at my rug. It also had yellow stains. The bag warns that this might happen. I should have listened. That was the last Chip Dip he\u2019ll ever get inside the house. The next one was offered outside on the deck, and that solved the problem of the coating transferring. The 16 ounce bag is huge and contains a lot of chews. At $17.97, I think it\u2019s a good value, especially considering how long each chew lasts.", rating: 5, sentiment: "positive" },
  { id: 56, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-02", customerName: "Amazon Customer", title: "A. delicious, long-lasting doggy treat", text: "I bought these long-lasting rawhide dog chews in the cheddar bacon flavor, and my dog seems to really enjoy them. The bag comes with a generous amount of chews, which makes it a good value compared to some other treats I\u2019ve tried. I also appreciate that the odor is not as strong or unpleasant as other rawhide products.\n\nMy dog is able to finish one within a few minutes, and he gets really excited when I give him one. So far, he has been able to digest them well with no stomach issues or changes in his behavior. I have not noticed any improvements in his coat, joints, or teeth yet, but I also have not been using these long enough to determine if they provide those benefits.\n\nAs with any chew treat, I always make sure to supervise my dog while he is eating it to make sure he is chewing safely. Overall, these have been a treat my dog enjoys, and I like that they keep him occupied for a little while without the strong rawhide smell.", rating: 5, sentiment: "positive" },
  { id: 57, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-02", customerName: "HeddaGabler", title: "Tasty treats but turned my dog orange \ud83d\ude02", text: "This is a huge bags of chews that are fairly lightweight but also quite substantial.\n\nMy dog was initially dubious, but he did eat it and seemed to enjoy it. I have a 75 pound Samoyed and it took him about 10-15 minutes to chew through this.\n\nThe quality does seem high! The reason for only four stars is that they dyed my dogs fur Cheeto orange! And it was damp from chewing so not immediately removable. I thought the powder might come off after a day or so, but it didn't so I had to comb the orange out.\n\nAnyway, if you have a light colored dog bear that in mind - a huge bag of great value, high quality and seemingly tasty treats that are fairly sturdy and long lasting and have good ingredients. But! The coloring is intense.", rating: 4, sentiment: "neutral" },
  { id: 58, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-02", customerName: "Amazon Customer", title: "Long-Lasting Chews That Keep My Dog Busy", text: "My dog can go through most treats in just a few minutes, but these collagen chews last noticeably longer. The cheddar bacon flavor seems to be a big hit, and my dog gets excited every time I grab one. I like that they're easier to digest than traditional rawhide while still providing a long-lasting chew. They also seem to help satisfy my dog's urge to chew on things around the house. The chews are consistently sized and haven't splintered or broken apart into sharp pieces during use. Considering how long each one lasts, I think they're a good value and something I'll continue buying", rating: 5, sentiment: "positive" },
  { id: 59, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-02", customerName: "Kristi Martin", title: "Great concept but so messy, got all over the carpet and my dog's paws and face", text: "My dog loves these Pet Factory Chip Dips Long Lasting Collagen Dog Chews for Aggressive Chewers, Easy to Digest Rawhide Dog Treats with Digest-A-Boost\u00ae, Flavor-Dipped Cheddar Bacon Blast Dog Chews, 16oz. I appreciate that they are collagen chips which are preferable over many other dog treats and that these are made so they are easy to digest. The chips are thin and flat making them easy for my dog to chew on and hold onto with her paws. However, the coating, which it does state in small print in the product description can transfer, makes a huge mess. Not only did the coating get all over the carpet but was all over her face and paws and I had to spot clean the carpet and use a wipe to clean it from her face and paws. I would not recommend these for a white dog or really any dog if you don\u2019t want the mess left behind. It is a shame, as these collagen chips come in a variety of flavors which I know my girl would enjoy but the mess isn\u2019t worth it to me. I did find that I could rinse off most of the outer dip coating which makes them less messy, but I am sure it also makes them less tasty to my dog and defeats the purpose of the flavor-dipped feature of these chews", rating: 3, sentiment: "negative" },
  { id: 60, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-03", customerName: "Amazon Customer", title: "dogs like them!", text: "I bought these cheddar bacon flavored collagen chews for my two dogs, a mix breed and an American Eskimo, both around 30 to 35 pounds. They both get pretty excited when I pull one out and will settle in to chew for a good while. The bag has a solid amount of treats so it feels like decent value, and the smell is much milder than other rawhide options I have tried.\n\nBoth dogs finish them without any stomach trouble or changes in their behavior, which is a relief since digestion can be hit or miss with chews. I always stay nearby while they work on one just to make sure everything goes smoothly. I have not used them long enough yet to notice any difference in their coats, joints, or teeth.\n\nOverall these have been a solid pick for us. My dogs enjoy them and they keep them busy without the strong odor that turns me off from other rawhide treats.", rating: 5, sentiment: "positive" },
  { id: 61, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-03", customerName: "Mrs Meyers", title: "Each chip lasted around 5-6 minutes or so for us", text: "I timed it, because long-lasting dog chips was not something I'd thought would be a myth. Chips in our house are eaten within about 5 seconds after the bag's open lol. My dog's about 45 pounds, middle aged, never had an issue with her teeth - and it took her about 5 minutes and 30 seconds from start to finish for a chip. Honestly, for just 1 think sheet of chip dip? That is pretty long lasting!\n\nIt's also a very large bag, I wish I got more of these in other flavors! I was skeptical when I should not have been! My dog really loves these, and it's long enough to provide a good night time treat before bed but not long enough you have to stay around forever to supervise them.\n\nOne thing - and I actually have no evidence besides my own anxiety - but I just watched my dog eat these...seems like how thin they are, they could be a choking hazard right? Again I have no clue.", rating: 5, sentiment: "positive" },
  { id: 62, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-03", customerName: "Christina", title: "They are long-lasting chews, and my dog loves them", text: "My dog absolutely loves these cheddar bacon dog chews! She gets so excited when I give her one, gets the zoomies, then runs to the bedroom to chew on it. I was surprised by how long it takes her to chew it, considering she usually gobbles up her treats very fast, so these really are for aggressive chewers, which is great. They keep her entertained for a long time. This also helps to support her dental health, and I like that they are 80% protein. I like the ingredients and that they are made in the USA. The expiration date is great, being 3 years out. I will be purchasing these again; they are definitely worth the price for this large 16 oz bag", rating: 5, sentiment: "positive" },
  { id: 63, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-04", customerName: "Amazon Customer", title: "Stomach issues. Don't smell horrible. Medium size dog gnawed for a while.", text: "My dog really liked the cheddar bacon flavor and stayed busy with it for quite a while. The chews have a little flex to them instead of being rock hard, but they still take my medium-sized dog a good amount of time to get through. She had no stomach issues afterward, and the beef hide seemed to agree with her. You get plenty of treats in the bag, so the value is good. If you have a dog that loves to chew, these are worth picking up. They don't smell too funky and they didn't leave a mess", rating: 4, sentiment: "positive" },
  { id: 64, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-04", customerName: "Lillian", title: "My dog loves this", text: "My dog really enjoys these chip-shaped collagen chews. The Cheddar Bacon Blast flavor must be appealing because he gets excited every time I give him one. They really do look like chips, but they're made specifically for dogs.\n\nThe chews don't have an unpleasant odor, at least not to me, and they're easy for my dog to chew. One thing I did notice is that the cheddar coating can leave a little color behind on fabric. My dog ate one on his bed, and I could see where he had been chewing, so I would recommend giving these treats on the floor, outside, or on a washable surface.\n\nI also like that they provide several benefits, including support for joints, skin and coat health, dental health, and protein intake. The ingredient list is straightforward and doesn't contain a lot of unnecessary or hard-to-pronounce ingredients. Most importantly, my dog has had no digestive issues while enjoying these treats. He's a big fan, and I'm happy with both the quality and the ingredients.", rating: 5, sentiment: "positive" },
  { id: 65, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-04", customerName: "Amazon Customer", title: "My dogs love them", text: "These dog chews come in a pretty large package. Upon opening, you can tell they have a pleasant smell. If the smell was anything like the taste, I knew they'd be a hit with my dogs. And yes, the dogs barely took a whiff and chomped down on it right away. My dogs love this flavor and I'm happy they're made in the USA. My dog has tried them and is acting fine though I don't think he has a sensitive stomach. He seems to have had no digestion issues whatsoever. The treats are reasonably priced and last a while. I'd recommend them to others.", rating: 5, sentiment: "positive" },
  { id: 66, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-04", customerName: "KM", title: "Long lasting for a heavy chewer", text: "Grabbed a pack of these collagen chews to keep the dogs busy and give them something tough to work on that lasts longer than standard treats. Finding chews that actually hold up against heavy chewing without disappearing in two minutes can be tough, but these can take a solid 30 minutes or so for the dogs to get through them. They are dense and dont smell horrible and arent like some of the other treats that I find stains on the carpets from. These seem to digest easy and the dogs love them. Good value", rating: 5, sentiment: "positive" },
  { id: 67, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-04", customerName: "Melace83", title: "Dog loves it", text: "Big and crunchy chips that last a long time. Your dog will absolutely love it and crave more.", rating: 5, sentiment: "positive" },
  { id: 68, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-05", customerName: "Amazon Customer", title: "Pros and Cons", text: "To start with the positives: This is an affordable treat option that dogs seem to genuinely enjoy. The Cheddar Bacon coating creates immediate interest, and the durable core keeps a dog occupied while offering a budget-friendly outlet for routine chewing. So there's that.\n\nHowever, despite the heavy marketing around \"collagen\" and proprietary terms like \"Digest-A-Boost\" (which lacks clear, transparent information), these are ultimately rawhide-based chews. Just so everyone knows, rawhide comes with well-documented risks, including potential intestinal blockages, choking hazards, poor overall digestibility, and the harsh chemical processing typically involved in manufacturing it. Splitting marketing hairs doesn't change the underlying material, so pet owners should exercise caution, monitor their animals closely during use, and weigh those inherent risks before handing these over. We use them, but it's not often, and I often wonder why these are still offered as a product type.", rating: 3, sentiment: "negative" },
  { id: 69, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-05", customerName: "Customer Review", title: "Nice quality treat, though my dog gets tired of chewing after a while", text: "These are a really nice unique treat for my dog. I love that they\u2019re made in the USA. I think they are a very fair value considering how large the bag is. I think these are high-quality. My Welsh Terrier was hesitant at first as she wasn\u2019t really sure what to make of these but once she got a taste, she immediately took it and spent quite a while chewing on it. She is a pretty significant chewer and I would say she spent at least 30 minutes with this and only ate about half of it. She seems to want to take a break from it as I assume all of the chewing might start to hurt her mouth a little. But she still doesn\u2019t want me to take this away from her. I think I will try to break these apart moving forward so that she doesn\u2019t have as big of a piece to work on at a time as I think her mouth just got tired honestly. Overall, I think these are an excellent special treat, especially for dogs that chew a lot as it actually takes them a while to consume it.", rating: 4, sentiment: "positive" },
  { id: 70, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-06", customerName: "Rebekah", title: "Dogs love them", text: "Both my dog and my neighbor's dogs are very food motivated, and love a good snack, and when my neighbor's kids are coming over for a snack, it feels cruel to have nothing for our furry friends. I picked these up because they seemed like something they would enjoy, and the chip shape would give me a little space to not get my fingers in the dogs' mouths when they get excited like it's the first time they've eaten in a week (to be clear, it's not LOL). They seem to really enjoy these and know the bag very well. When they see me grab it, they come running over and sit for me. Needless to say, they're a hit. There's a generous amount in the bag and they'll last a good while I hope.", rating: 5, sentiment: "positive" },
  { id: 71, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-06", customerName: "Amazon Customer", title: "A Favorite Treat for Our Pups", text: "Our pups absolutely love these chews! They keep them happy and entertained, and I love that they\u2019re made with collagen. They\u2019re a great treat option that our dogs get excited about every time they see them. The size and texture are perfect for chewing, and they seem to last a good amount of time compared to other treats we\u2019ve tried. Definitely a favorite in our house!", rating: 5, sentiment: "positive" },
  { id: 72, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-08", customerName: "Coffee & Feathers", title: "A rare chew that actually keep my aggressive chewers occupied!", text: "Both of my large breed pups are aggressive chewers, and they are absolutely obsessed with these! One \u201cchip\u201d keeps them occupied for quite a while, which is impressive with my dogs.\n\nThese are made from beefhide as a source of collagen, so I definitely supervise while my dogs are chewing them. As you can see in my photos, they soften and get thinner as they\u2019re chewed. Once a piece gets small enough that I\u2019m concerned they could swallow it whole, I take it away.\n\nYou get a surprisingly generous amount in the 16 oz bag. At $17.97 at the time of my review, I think these are an excellent value, especially considering how much enjoyment my dogs get out of them. The cheddar bacon flavor is clearly a hit!\n\nMy Smokey and Charlie Ann LOVE these, and I\u2019ll absolutely buy them again", rating: 5, sentiment: "positive" },
  { id: 73, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-09", customerName: "Abby", title: "Lasts a good amount of time, perfect size for small dogs", text: "My pup loves these. The bag is huge and contains a ton of bite sized chews. Sometimes chews are huge and I don't want to give them to my dog unsupervised because he'll eat the whole thing and have digestion issues. These chews are the perfect size for him, I can give them to him in crate and he'll take like 20 minutes to finish it and I don't have to worry that he's eating way too much of a chew. He really enjoys them and I am always glad to have truly long lasting chews so he isn't as bored when he's in his crate. I'd definitely recommend these overall if you are looking for smaller sized but long lasting chews.", rating: 5, sentiment: "positive" },
  { id: 74, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-09", customerName: "Evie C", title: "My Dog Enjoys These", text: "These chews were an immediate hit with my dog and the cheddar bacon flavor definitely seems to get his attention. The pieces are a good size and have a firm texture, so they keep him occupied longer than softer treats that disappear in a few seconds. I like that the bag is large and contains a generous amount, especially if you give chews regularly. They don't crumble all over the floor while he's working on one. The smell is noticeable when opening the bag, but nothing too unusual for a flavored dog chew. My dog stays interested in them from beginning to end and always seems excited when I take the bag out. Overall, these have been an enjoyable longer-lasting treat for him and a nice option to keep around.", rating: 5, sentiment: "positive" },
  { id: 75, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-09", customerName: "Amazon Customer", title: "My Dog's New Chew Obsession (and My Wallet's Friend)", text: "I picked up these collagen chews expecting my dog to finish them quickly, but they actually kept her busy for quite a while. The Cheddar Bacon Blast flavor was clearly a favorite, since she stayed interested until it was completely gone. The bag is a decent size, so I won\u2019t need to restock every week, and I didn\u2019t notice any stomach upset. Overall, these seem like a good option for dogs that are serious chewers.", rating: 5, sentiment: "positive" },
  { id: 76, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-11", customerName: "Donna", title: "Long lasting favorite, just watch for coating transfer", text: "I picked these up for my dog who is a picky eater when it comes to treats, and the Cheddar Bacon Blast flavor won her over almost instantly. She sniffed it for a few seconds and then settled in on the living room floor for a good chew session. It took her close to twenty minutes to work through one chip, which is exactly what I wanted since I use these to keep her occupied while I am cooking dinner.\n\nThe smell is much milder than other rawhide treats I have tried in the past, which I really appreciate since some of the ones we have used before left the whole kitchen smelling odd. My dog did not have any stomach upset afterward, and she was excited to see the bag again the next day, tail wagging the second she heard the crinkle.\n\nOne thing worth mentioning, the coating does transfer. My dog has a lighter colored coat, and after she finished her chew her paws and the fur around her mouth had a slight yellow tint. It washed off easily with a damp cloth, but I would recommend giving these outside or somewhere easy to clean if your dog is light colored.\n\nThe bag itself is generously sized, so this should last us quite a while between chews. I always stay in the room while she is working on one, just to be safe, but overall this has become one of her favorite treats and I plan to keep this flavor in our regular rotation.", rating: 5, sentiment: "positive" },
  { id: 77, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-12", customerName: "Amazon Customer", title: "Long lasting treats but be careful where they eat it", text: "My dogs absolutely love these chews! They take quite a while to finish just one, which is a huge plus because it keeps them entertained and occupied for a good stretch of time.\n\n\u200bThe cheese flavor is clearly very savory because my dogs go crazy for them and truly enjoy every bite. It is a great option for heavy chewers who need something to work on.\n\u200b\nThe only downside is that as the chew gets soggy while they work on it, they tend to hold it down with their paws. This leaves the fur on their paws pretty sticky afterward, so you might need to wipe them down when they finish.\n\u200b\nOverall, if you are looking for a long-lasting, flavor-packed treat that keeps your dogs busy, these are definitely worth picking up!", rating: 4, sentiment: "positive" },
  { id: 78, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-12", customerName: "BadBullfrog", title: "Great healthy doggie treats that our pup loves", text: "Our lab loves these Pet Factory flavored snacks. She's just a little over a year old and still has a huge chew need and these collogen chips really help. The only downside is that because we keep the bag on top of our refrigerator, she follows us to the kitchen all the time now, just hoping she will get another treat! I've noticed no issues or changes with her bowel movements so no worries there, even when she's had more than one a day.\nOne word of warning; these do leave staining if you let your dog eat them on carpets or furniture. The stains wash off, but the wife-unit was none to pleased to find the orange stain on the carpet! Now I only give our pup these treats outside!", rating: 5, sentiment: "positive" },
  { id: 79, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-13", customerName: "Amazon Customer", title: "Really works their jaw", text: "Finding things that keep our large pup occupied is always a win. These cheddar bacon treats are definitely more for big dogs though because they have a very hard, chewy consistency that my smaller pups would struggle with. Our big dog though goes absolutely crazy for the flavor, and the price value for a big sixteen ounce bag is really reasonable compared to other specialty chews we have bought. However, you do have to keep an eye on things because it requires supervision as the pieces break down during heavy chewing. My husband and I always make sure we are in the room when he is working on one, just to be sure he does not swallow any large chunks. Corners in particular can look a little sharp. Still, they are great for his teeth and digest well it seems as no GI issues here, making them a good value to me.", rating: 4, sentiment: "positive" },
  { id: 80, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-17", customerName: "Amazon Customer", title: "Long lasting chew that is easy on stomachs", text: "I\u2019m always on the hunt for chews that can withstand my dog\u2019s aggressive chewing habits, and these Pet Factory Chip Dips are exactly what I\u2019ve been looking for. It is incredibly hard to find treats that keep him occupied for a good amount of time without worrying about potential digestion issues, but these collagen chews are the perfect solution.\n\nThe Digest-A-Boost technology is a total amazing; I\u2019ve noticed zero stomach upset, which is a huge relief compared to other chews we've tried in the past. As for the flavor, the Cheddar Bacon Blast is clearly a massive success, my dog is obsessed with it and gets excited the moment he sees the bag. These are high quality, long lasting, and offer the perfect balance of durability and digestibility. I'll definitely be keeping these stocked!", rating: 5, sentiment: "positive" },
  { id: 81, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-17", customerName: "3 Generations", title: "Harley approved treats!", text: "The Pet Factory Chip Dips Dog Treats work well for Harley. I wouldn\u2019t call her an aggressive chewer, but she has been through dozens of toys. She\u2019s more persistent than anything, and these are easy for her to digest.\nI have both flavors Cheddar Bacon Blast and Backyard BBQ. She loves both of them but actually leans to the cheddar bacon one more. They keep her busy and out of trouble, and I like that they\u2019re natural treats. The chews last her a good amount of time, and she gets excited every time I open the bag. It\u2019s a huge 16oz resealable bag to keep moisture out and will last us quite some time, especially since she gets these as her \u201cstay busy\u201d treats. The treats don't have any weird smell and actually have a nice crunch texture to them.", rating: 5, sentiment: "positive" },
  { id: 82, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-18", customerName: "Amazon Customer", title: "My Dogs Loved These Chews", text: "I picked these up as something a little different from the usual dog treats, and my dogs were immediately interested. The cheddar and bacon flavor combination seems to be a big hit, and they were happy to settle in and chew on them.\n\nThe chews are definitely more substantial than a typical dog treat, and they kept my dogs occupied for quite a while. They aren't truly indestructible, but they've held up longer than many of the softer chews I've purchased for my dogs.\n\nI also like the flavor coating because it seems to make the chews more appealing without having an overwhelming smell throughout the house. My dogs don't need much convincing when it comes to treats, but they were particularly interested in these.\n\nThe size makes them better suited for medium to large dogs or dogs that are strong chewers. As with any chew, I would recommend supervising your dog while they're using it and making sure they don't try to swallow large pieces.\n\nOverall, these have been a successful addition to our treat rotation. My dogs enjoy the flavor, the chews keep them occupied, and they last longer than many of the treats they normally go through quickly.", rating: 5, sentiment: "positive" },
  { id: 83, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-08-20", customerName: "Demetrios", title: "MY DOG DISLIKES THESE", text: "I PERSONALLY DO MOT CONSUME MALTODEXTRIN AND AVOID IT ! I SEE NO REASON FORY DOG TO CONSUME IT , SINCE HE LIKES DOG CHEWS AND HE WILL EAT THEM HE TRIED THIS AND DOESNT LIKE IT AT ALL", rating: 1, sentiment: "negative" },
  { id: 84, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-09-08", customerName: "Steve", title: "A Long-Lasting Chew Our Dog Goes Crazy For, With One Staining Caveat", text: "Our dog has been a fan of these cheddar bacon flavored chips since the first one came out of the bag, tail wagging the second she hears the crinkle. Each chew keeps her occupied for a solid twenty to thirty minutes depending on how aggressively she's working on it, which is exactly what's needed when dinner prep is happening and she needs something to do. The smell is noticeably milder than traditional rawhide, which makes a real difference in a smaller house. The one thing worth knowing upfront is that the coating transfers, so giving these on carpet or furniture is asking for an orange stain that requires cleanup. Take them outside or on an easy-to-wipe surface and that problem goes away entirely. No digestive issues after several uses, and the bag is generous enough to last a good while. As with any chew, supervision is recommended since rawhide-based products carry inherent risks with aggressive chewers.", rating: 5, sentiment: "positive" },
  { id: 85, asin: "B07Q6C49BL", itemName: "Chip Dip Cheddar Bacon", date: "2026-09-12", customerName: "Maria", title: "Causes stained furniture", text: "Stains couch with yellow color", rating: 1, sentiment: "negative" },
  { id: 86, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-02", customerName: "Dan", title: "My dog absolutely loves these!", text: "My dog gets excited every time I reach for one of these treats. She seems to absolutely love them and settles right down to chew on them. They keep her occupied for a while, and I like that they don't make the kind of mess some other dog chews do. They've been a big hit in our house, and I'll definitely keep giving them to her. I think these are a good value and I would recommend them.", rating: 5, sentiment: "positive" },
  { id: 87, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-02", customerName: "Kristi Martin", title: "So messy, the coating got all over everything", text: "My dog loves Pet Factory Chip Dips Long Lasting Collagen Dog Chews for Aggressive Chewers, Easy to Digest Rawhide Dog Treats with Digest-A-Boost\u00ae, Flavor-Dipped Chicken N Waffles Dog Chews, 16o. I appreciate that they are collagen chips which are preferable over many other dog treats and that these are made so they are easy to digest. The chicken and waffles flavor is a cute option for dogs since that is such a popular meal for humans these days. The chips are thin and flat making them easy for my dog to chew on and hold onto with her paws. However, the coating, which it does state in small print in the product description, can transfer, makes a huge mess. Not only did the coating get all over the carpet but was all over her face and paws and I had to spot clean the carpet and use a wipe to clean it from her face and paws. I would not recommend these for a white dog or really any dog if you don\u2019t want the mess left behind. It is a shame, as these collagen chips come in a variety of flavors which I know my girl would enjoy but the mess isn\u2019t worth it to me. I did find that I could rinse off most of the outer dip coating which makes them less messy, but I am sure it also makes them less tasty to my dog and defeats the purpose of the flavor-dipped feature of these chews.", rating: 3, sentiment: "negative" },
  { id: 88, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-03", customerName: "Amazon Customer", title: "dogs are ok with these", text: "I bought the Chicken N Waffles flavor of these Pet Factory Chip Dips collagen chews for my two dogs, a mix breed and an American Eskimo who both weigh around 30 to 35 pounds. The bag has a solid amount of chews for the price, which feels like good value. The smell is milder than a lot of other rawhide style treats I have tried, and that is a nice change.\n\nBoth dogs will eat them and have had no stomach issues so far. My mix breed gets pretty excited and finishes one in just a few minutes, while my Eskimo is more neutral and sometimes leaves it until he is actually hungry. They keep them busy for a short while, though not as long as I hoped for more aggressive chewers.\n\nI always supervise them while they chew, just to be safe. I have not noticed any changes in their coats, joints, or teeth yet, but I have not been using these long enough to judge that. Overall they are a decent everyday treat option that both dogs will take without any problems.", rating: 4, sentiment: "neutral" },
  { id: 89, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-03", customerName: "Ajax", title: "Fun and unique treat!", text: "These 'chips' were a novel enough treat that I had to try them out for my dogs. My Great Pyrenees is a notoriously picky eater, but she loved these. She demolished hers in less than 10 minutes. At 115lbs, hardly any treat lasts long in her jaws. My 35 lbs Aussie, however, took much longer to savor his. This treat is no match for an aggressive chewer, but the price point makes this a contendor for the rotation. It was a wonderful value for the money, and both of my dogs enjoyed it. The chips were all generously sized. Any dog under 30lbs might struggle a little with the size of these treats.", rating: 5, sentiment: "positive" },
  { id: 90, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-04", customerName: "Amazon Customer", title: "My dog loves these!", text: "The Chicken and Waffles Chip Dips proved to be a good choice for my dog. He\u2019s picky enough that I never assume a new flavor will work, but he warmed up to this one pretty quickly. He has enjoyed Chip Dips before so he knew just what to do when I handed him the chew. He settled in to chew without hesitation and did not stop until it was gone. These chews last him a good amount of time, which is exactly what I want. The texture of these gives him something to really work on. I try to give him one per day because they help keep his teeth cleaner and will hopefully prolong the time until he needs a cleaning. The coating on these Chip Dips does transfer. I\u2019ve learned to give him Chip Dips either outside or on a towel because the color ends up on his paws and the rug if I don;t protect against it. It\u2019s not a deal\u2011breaker, but it\u2019s something to plan for. The ingredient list on this bag matches the listing, which I appreciate because some of the other flavors didn\u2019t. The ingredients are beefhide, maltodextrin, natural chicken flavor, natural apple cinnamon flavor, brewer\u2019s dried yeast, caramel color, guar gum, and salt. The bag is a full 16 ounces, and it contains a generous number of chews. At $17.97, I think the price is fair for how long they last and how much my dog enjoys them. They\u2019re made in the USA, and the quality has been consistent across the flavors we\u2019ve tried.", rating: 5, sentiment: "positive" },
  { id: 91, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-04", customerName: "Amazon Customer", title: "The dogs take to these chews immediately", text: "These a good rawhide treats that are made in the USA so I'm happy to give them to my dog. He likes them and is happy to have one when offered. He will chew them about halfway and then leave the rest and I end up disposing of it. He does that with all rawhide so that's nothing new. He's had no digestive issues from eating them so they're gentle on his stomach. He's had treats in the past which did upset his stomach so I try to be careful what I let him have. These seem to be made of quality ingredients and their priced fairly. I'd have no issues replacing them with the same treats in the future.", rating: 5, sentiment: "positive" },
  { id: 92, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-04", customerName: "Life with Dogs \ud83d\udc3e", title: "My dogs love these chews!", text: "These chicken and waffle flavored chews are a big hit with my dogs! They are the perfect treats to keep my dogs occupied and happy when we need some quiet time for work, or watching a movie.\n\nMy dogs love the taste of these chews! They can be picky eaters, but they both take these without hesitation. All of the chews in the bag are a good size, and they are easy for them to hold between their paws.\n\nThis bag of chews is quite a bit larger than I expected, so they are a great value. Since we only give them these types of treats occasionally, it will be months before we need to buy more.", rating: 5, sentiment: "positive" },
  { id: 93, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-04", customerName: "Hailey", title: "Great Dog Chews", text: "These dog chews are very nice. They are high quality. They actually lasted longer than I expected for my dog who chews through everything. The chicken and waffle flavor must taste good because they kept her occupied. The collagen is nice to be able to incorporate into their diet. The size of the chips are pretty large, and the bag overall is a generous size. Good value. Definitely recommend for aggressive chewers", rating: 5, sentiment: "positive" },
  { id: 94, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-05", customerName: "Amazon Customer", title: "A fun flavored rawhide treat for dogs", text: "These chip dip chews from Pet Factory are a HUGE hit for my dog. The chicken n waffle flavor is great, and a fun, different kind of flavor than most dog treats I've seen.\n\nThe ingredients to these seem to be pretty good. As with all rawhide products, it's a good idea to keep an eye on your dog as they're chewing to avoid them swallowing large chunks or choking, but so far my dog has been fine with eating these. These are collagen based, so they're more digestable and less likely to cause blockages than traditional rawhide is, which is nice.\n\nMy dog absolutely loves them and they're a great way to keep her busy and distracted for a bit. The chews themselves are small to medium sized, so it doesn't take her that long to get through one, but they're good for a nice 10-15 minute distraction. They're great for an occasional treat as a reward as well. The bag is huge, and since she's just one little dog, one bag will last us a while before we'd need more, so they feel like a great value.", rating: 5, sentiment: "positive" },
  { id: 95, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-05", customerName: "NoneYasEver", title: "Pet Factory Chip Dips Long Lasting Collagen Dog Chews", text: "My dog is extremely picky when it comes to food and treats. These dog chews are pretty good, and I love that they contain collagen and are easy on her tummy. I would not say that they last very long, but that's because my pup is a very aggressive chewer. Otherwise, they're great, and she seems to love the texture and taste.", rating: 4, sentiment: "positive" },
  { id: 96, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-05", customerName: "Vine Reviewer", title: "My Dogs Wouldn't Touch Them", text: "My dogs would not eat these. I am fully aware that my dogs are extremely picky about their rawhide treats and only eat 25% of the ones i give them, so I'm only knocking off one star because I know my dogs are picky. But the fact remains, I gave each of my dogs one of these and both of them dropped them and they're still sitting on the floor untouched and ignored a week later. The rawhide chips seem to be well made and they don't have any bad odors to them. The bag was well sealed. I'm not sure what is in these that puts my dogs off, but they have no interest.", rating: 4, sentiment: "negative" },
  { id: 97, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-05", customerName: "Tanya", title: "A hit with the pups!", text: "These chews were a hit with my mom's dog! He really enjoys the chicken and waffle flavor (maybe more than the peanut butter) and gets excited when he sees the bag come out. He's an aggressive chewer and these lasted several minutes.\n\nI also appreciate that these are collagen-based and easy to digest compared to traditional rawhide chews. The 16 oz resealable bag is a great size and helps keep the treats fresh between uses. They're a good value for the quantity you get, and I like that they are made in the USA.\n\nOverall, these are a great option for dogs that need longer-lasting chews!", rating: 5, sentiment: "positive" },
  { id: 98, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-06", customerName: "CB", title: "Rawhide is Rawhide", text: "To start with the positives: this is an affordable treat option that dogs genuinely enjoy. The \"Chicken and Waffle\" coating creates immediate interest, and the durable core keeps dogs occupied while offering a budget-friendly outlet for routine chewing. The photos on the packaging made me reconsider what I was having for dinner.\n\nThat said, the heavy marketing around terms like \u201ccollagen\" and \u201cDigest-A-Boost\" can make the product sound more specialized than it is. At its core, these are rawhide-based chews, and that means pet owners should keep the well-known concerns in mind, including choking hazards, digestive issues, and the need for close supervision during use. For dogs that do well with rawhide, these can be a fun occasional treat, but I would still recommend using them cautiously and not as an everyday chew.", rating: 3, sentiment: "neutral" },
  { id: 99, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-06", customerName: "Amazon Customer", title: "Great!", text: "Item came as described and as pictured. Both of our dogs were immediately interested upon seeing the bag and sniffing the air the moment the seal was broken. We have a smaller and a larger dog, and I definitely would be weary of giving these to a dog that is small as these are fairly large and hard to break apart. Definitely not for dogs who do not or will not take the tie to actually taste something and instead think they should be inhaling their surroundings... this is a hard and long lasting CHEW not treat! For further context, our large pitt chewed on one of these bad boys for over 20 minutes and still didnt really put a dent in it. Literally buried it for later in the backyard lol. Overall they seem to be good chews but i would only recommend for larger dogs out of fear of possible choing hazard", rating: 5, sentiment: "positive" },
  { id: 100, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-06", customerName: "Kiki Scoggins", title: "My dog was an instant fan", text: "My dog absolutely loves these chews. As soon as I opened the bag, he was excited, and they keep him happily occupied for a good amount of time instead of disappearing in a couple of minutes like some treats do. They seem to be a nice balance of being long-lasting without being overly hard.\n\nOne thing I always watch for with new chews is whether they upset his stomach, but he had no digestive issues at all after eating these. They\u2019ve agreed with him well, and he\u2019s always eager for another.\n\nIf your dog enjoys collagen chews, these are definitely worth trying. Mine gives them two paws up!", rating: 5, sentiment: "positive" },
  { id: 101, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-06", customerName: "MT2", title: "Big bag, big treats, happy dog", text: "The bag is big and the treats are too. I got these for my neighbor's dog who always comes to my fence looking for the love his owner does not give him. He goes crazy for these. He takes the treat, looks me directly in the eyes, bows as if saying thank you, and then goes back to his sad life. It breaks my heart but I am so happy I can make him happy, even if just for a little while, with these treats. He loves them and I will keep buying them for him.", rating: 5, sentiment: "positive" },
  { id: 102, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-07", customerName: "Discerning Reviewer", title: "Great rawhide-like chews for large dogs", text: "These are great rawhide-like chews for large dogs. My labs absolutely adore them and were trying to snag each other's after finishing their own! They have \"natural chicken flavor\" rather than actual chicken. Each chew lasted awhile for my large aggressive-chewer dogs; I like that they're cleaning their teeth while snacking. The bag is pretty large and should last for awhile. The price is reasonable for the quantity of chews and in line with what I'd expect to pay in a store. I'd order these again in a heartbeat.", rating: 5, sentiment: "positive" },
  { id: 103, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-08", customerName: "Merry Mayhem", title: "Not the most enticing flavor, but my dog warmed up to it", text: "I've recently purchased this chicken and waffles flavor and the peanut butter flavor, and had the same basic experience with both of these flavors. I think the idea of the flavors is better and may appeal more to humans than actually works in practice with dogs.\n\nI have a GSD rescue, a GSD/Malinois mix rescue, and a senior Samoyed. My senior Samoyed is pretty picky about treats, so I wasn't surprised that she snubbed these. My GSD boy also tends to be picky and not terribly food motivated, and he was also not super excited about these. My GSD/Mal rescue girl accepted them, but wasn't overly enthusiastic. These chips are varied in size and they're pretty thin. My GSD/Mal had no problem chewing them or digesting them. She noses the bag, so clearly they're a hit with her. Because they're coated in the flavor, I was worried about staining on my carpets or my girls bed, but we didn't have any issues with that. She doesn't tend to drop her treats--she just chews and devours, so your mileage may vary on that.\n\nI like that these are made in the USA and do seem to be high quality. I didn't dock a star because my two picky dogs weren't into them, but I think maybe they'd be enticed with a different flavor because it took a few minutes for my dog who is more treat and food motivated to warm up to them", rating: 4, sentiment: "neutral" },
  { id: 104, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-08", customerName: "Coffee & Feathers", title: "Chicken n waffles! My dogs are obsessed!", text: "The chicken n waffles flavor is clearly a big hit!\n\nBoth of my large breed pups are aggressive chewers, and they are absolutely obsessed with these! One \u201cchip\u201d keeps them occupied for quite a while, which is impressive with my dogs.\n\nThese are made from beefhide as a source of collagen, so I definitely supervise while my dogs are chewing them. As you can see in my photos, they soften and get thinner as they\u2019re chewed. Once a piece gets small enough that I\u2019m concerned they could swallow it whole, I take it away.\n\nYou get a surprisingly generous amount in the 16 oz bag. At $17.97 at the time of my review, I think these are an excellent value, especially considering how much enjoyment my dogs get out of them.\n\nMy Smokey and Charlie Ann LOVE these, and I\u2019ll absolutely order more when we run out!", rating: 5, sentiment: "positive" },
  { id: 105, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-08", customerName: "Amazon Customer", title: "Picky Maremmas didn\u2019t like them", text: "My dogs sniffed around me with interest as I was opening the bag of these Pet Factory rawhide treats, but they both said, \u201cNo thank you\u201d pretty quickly after receiving them. I decided to try again on a couple other days because my Maremmas are picky eaters and sometimes warm up to new foods over time, but so far they have continued to reject these. Of all the flavors, I\u2019d been pretty confident that Chicken 'N Waffles would be one they\u2019d enjoy, so I was surprised.\n\nI like that the ingredients are simple, and could do without the added color, but otherwise feel good about my dogs eating these treats. They also do like to chew on stuff, so I\u2019d been hoping these long lasting chips would meet that need for them as well. The treats are a great size that would have been ideal for my large breed dogs, and the bag feels substantial and is resealable.\n\nI'm bummed my dogs don't like them, but since they are notoriously picky, I would still recommend these for other dogs", rating: 4, sentiment: "negative" },
  { id: 106, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-08", customerName: "Amazon Customer", title: "These are a hit with my dogs, the flavor is irresistible and the texture withstands heavy chewing", text: "These Pet Factory Chip Dips dog chews are packed with flavor and have a scent my dogs can\u2019t resist. This bag comes with a large amount of treats, they are naturally prepared and dried so they feature random shapes and sizes that dogs love and will enjoy more chewing on. Considering my aggressive chewers, these treats actually lasted for a good while with them and kept them busy. They seemed to really love the flavor. I like that the bag has a ziplock style closure that lets me store them easily and keeps the treats dry and fresh for next use. I love that these chewable treats are made with good and healthy ingredients only. Good quality, good value! These have definitely earned my dogs\u2019 recommendation!", rating: 5, sentiment: "positive" },
  { id: 107, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-08", customerName: "Amazon Customer", title: "Dog only kind of liked", text: "Unfortunately the dog didn't like these. I noticed that there wasn't really any smell to them the way dog treats usually have a smell that seems appealing to dogs. This doesn't have that. These are basically like a raw hide with some kind of coating on them. Because it's chicken and waffle flavored, I would assume there's a bit of sweet taste for the dog, but obviously there's no way to know that. I tested these with a dog who's not food motivated but does like to chew. The first one , he wouldn't touch it , he just kept walking past it and sniffing it. The second one he finally decided to chew, so I don't know if that means there's inconsistency to the flavor or smell of these, at least that a dog can perceive? Overall , I'd call these average treats with an average appeal to dogs.", rating: 3, sentiment: "negative" },
  { id: 108, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-10", customerName: "Collagen Dog Chews", title: "Collagen Dog Chews", text: "My dog was definitely a fan of these! The Chicken 'N Waffles flavor apparently gets his approval, and the pieces give him something satisfying to chew rather than disappearing in a few seconds like many treats.\n\nI like that these are collagen-based chews and that the bag contains a generous 16 ounces. The chip-style pieces are also convenient because they're easier to portion than a large traditional chew.\n\nThey have a good texture for chewing and keep my dog occupied for a while. As with any chew, I supervise while he's eating one and take away any pieces that become small enough to swallow whole.\n\nOverall, these have been a hit with my dog, and I like the combination of a satisfying chew in a convenient, easy-to-portion size. \u2b50\u2b50\u2b50\u2b50\u2b50", rating: 5, sentiment: "positive" },
  { id: 109, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-13", customerName: "Monica McConnell", title: "My dogs are happy so I am happy", text: " I have to start off by saying anytime that you're going to give your dog a rawhide treat, please do so while you are supervising them. If you do not know, they are a choking hazard and can cause multiple issues. With that being said, I was raised with parents who gave our animals rawhide and we never had any issues so I still give it to my dogs and they love them. I do supervise them though when I give it to them. I have to say my dogs absolutely love these. The chicken and waffle flavor is apparently very appetizing to them. I like that they're already smaller, thinner pieces than a lot of the other rawhide treats. I think that really helps lessen the chance of any issues. I do break them up even smaller but you of course do not have to. I can say that so far we have had no issues. So far, my dogs are more than happy with them so that means as long as they're happy, I'm happy.", rating: 5, sentiment: "positive" },
  { id: 110, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-14", customerName: "Homesteading Mama", title: "My dogs go absolutely BONKERS for these!", text: "I love giving my dogs something appropriate to chew because chewing is such an important part of enrichment and gives them a great outlet for all that chewing energy. That said, I\u2019m always cautious with dog chews after learning about the concerns surrounding traditional rawhide.\n\nWhat I really like about these is that they\u2019re a collagen-based chew rather than a traditional rawhide chew. Collagen chews are generally considered a more digestible alternative to conventional rawhide, and this particular formula also contains DIGEST-A-BOOST, which is designed with easier digestion in mind. Of course, I still supervise my dogs anytime they have an edible chew, because there\u2019s really no chew that\u2019s completely risk-free, especially with enthusiastic chewers.\n\nMy dogs are medium-to-large and definitely on the medium-power-chewer side. These usually keep them occupied for around 20 minutes, which is actually pretty impressive for my dogs. Even bully sticks don\u2019t always make it 30\u201340 minutes with them! They get a really satisfying chewing session out of these, and I like that they have a durable collagen core instead of just being a quick little treat.\n\nThe Chicken 'N Waffles flavor is clearly a winner in this house. \ud83d\ude02 I also appreciate that these are made with a collagen core and are high in protein. The added collagen is a nice bonus, particularly since collagen is associated with supporting connective tissue, joints, and mobility, although I view that as an added benefit rather than the reason I\u2019m buying these. My two breeds of dogs are prone to joint issues as they age. So I try to give them a boost wherever I can.\n\nAnother BIG plus for me is that they aren't greasy, flaky, or super messy. Some chews leave a pile of crumbs or powder in the bottom of the treat container, and these have been much cleaner for us. They also don't have that absolutely awful smell that some natural dog chews can have. I keep ours in a dog treat bowl with an airtight lid, and they've held up well stored that way.\n\nI\u2019m also pretty conservative with how many I give my dogs. They generally get one a day at most, and sometimes I\u2019ll give them one every other day rather than making them an daily chew. I stay nearby and supervise them while they chew, especially as the piece gets smaller, just in case they try to swallow a larger piece.\n\nOverall, these have been a really nice alternative to the traditional rawhide-style chews I\u2019ve avoided. My dogs get the chewing stimulation they love, they stay occupied for a decent amount of time, they aren't left with a greasy or crumb-filled mess, and I feel better about the collagen-based formulation. Most importantly, my dogs clearly think these are AWESOME, which is probably the highest review they can get around here!\n\nIf I left my dogs to review this it would go something like, \ud83d\udc36 \u201cOkay, listen. We have personally tested these Chicken \u2019N Waffles thingies, and we have some important feedback. THEY ARE DELICIOUS. We chewed them, we conquered them, and we would like to formally request that Mom stops saying \u2018one a day\u2019 because that is simply unacceptable. Also, please do not listen to Mom when she says we\u2019re \u2018power chewers.\u2019 We prefer the term highly dedicated professionals for testing purposes of course. 10/10. Would chew again.\u201d \ud83d\udc3e\ud83d\ude02", rating: 5, sentiment: "positive" },
  { id: 111, asin: "B07Q7FJ8PC", itemName: "Chip Dip Chicken & Waffles", date: "2026-08-22", customerName: "AliasSmithNJones", title: "Chews that dogs love", text: "This is a 16 oz resealable zip top bag of Chip Dips in Chicken N Waffles flavor, from Pet Factory. It arrived fresh and factory sealed. These are rawhide type collagen chew treats for dogs, coated with a flavoring that apparently tastes like chicken and waffles. These are a healthy treat with a high protein content. Although rawhide type treats sometimes have a bit of a bad rep for digestibility, these are a more reasonable size and somewhat thinner than most, and are treated with enzymes to help improve digestion. These are chips, and are in a variety of sizes roughly between 3 and 5 inches. They are suitable for most sizes of dog, and dogs really love them. At the current price of $17.97 for the 1 lb bag, I think these are a good value.", rating: 5, sentiment: "positive" },
  { id: 112, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-02", customerName: "Amazon Customer", title: "Long lasting chew is great for his teeth and gums", text: "My dog is particular about both textures and flavors, and peanut butter is never a guaranteed win with him. Sometimes he\u2019s all in, and other times he walks away. That made this Peanut Butter Crunch flavor a bit of a gamble. Even though he already knows and likes Chip Dips from the Cheddar Bacon Blast and Backyard BBQ varieties, this one didn\u2019t grab him right away. It took some coaxing before he finally accepted the chew. He refused to settle down with it outside, so I had to bring it indoors for him to relax enough to start chewing. Once he committed, he stayed with it until it was completely gone. Because his teeth needed attention when he first came to us, I use chews like this as part of his dental routine. I limit him to one Chip Dip per day, but my goal is to give them regularly to help support his teeth and gums. The firm texture gives him something to really work on, and even if the flavor wasn\u2019t his favorite of the three we have tried, he still seemed to enjoy it once he got going. One thing you absolutely need to know is that the coating on these Chip Dips transfers. My dog is solid white, and his paws and mouth end up the same color as the coating. The floor does too. I learned that the hard way the first time I gave him a Chip Dip on a bare rug. Now I treat them as outside chews. With this Peanut Butter Crunch flavor, it was too hard for him to settle down to chew outside, so I covered my rug with a towel before letting him have it indoors. I strongly recommend avoiding bare rugs or carpet unless you\u2019re prepared for staining. I have included a picture of the staining on the towel after he finished his Chip Dip. The ingredients on the listing are not accurate. The actual bag lists the ingredients as beefhide, maltodextrin, artificial peanut butter flavor, brewer\u2019s dried yeast, caramel (color), guar gum, and salt. The expiration date on my bag is 35 months in the future, which gives us more than enough time to use them up. The 16 ounce bag contains a generous number of chews, and at $17.97, I think the value is good. I appreciate that they are made in the USA. Even though Peanut Butter Crunch wasn\u2019t as instantly appealing to my picky dog as the other flavors, it still delivered a good chewing session. I won't deduct any stars due to my dog's picky nature with flavors because I don't think that is fair. He's a weirdo.", rating: 5, sentiment: "positive" },
  { id: 113, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-02", customerName: "Amazon Customer", title: "Good dog treats, but maybe it needs some jelly with that peanut butter?", text: "I tried these peanut butter flavored long-lasting rawhide chews with my dog, and his reaction has been pretty neutral. He will eat them, but he definitely does not get overly excited or run over when he sees one, as he does with some of his favorite treats. Most of the time, he will take the chew and leave it sitting around until he is actually hungry and wants something to snack on.\n\nThe bag comes with a nice quantity of chews, so I think it offers good value for the price. The smell is also not as overpowering as some other rawhide treats I have tried, which is a plus. My dog has been able to digest them without any stomach problems, and I have not noticed any negative reactions.\n\nThese seem like a decent chew option, especially if your dog is not too picky. My dog will eat them, but they are not something he gets excited about. I think they may be more appealing to dogs that are less particular about their treats.", rating: 4, sentiment: "neutral" },
  { id: 114, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-02", customerName: "sam", title: "Happy Tail Treat Time Fun", text: "My beagle has a pretty good nose for treats, and these definitely got his attention the second I opened the bag. The chips have a nice crunch without being rock hard, so I didn\u2019t worry about him struggling to chew them. I also liked that I could easily snap larger pieces into smaller rewards during training. He kept coming back hoping I\u2019d forgotten where I put the bag.\n\nThe peanut butter smell is noticeable but not overwhelming, which I appreciated since some dog treats can be a little much indoors. They didn\u2019t leave greasy crumbs all over the floor either. The collagen ingredient was one of the reasons I picked these, and it\u2019s nice finding a chew that feels like more than just a snack. The only thing I\u2019d change is making the pieces a little more uniform since a few were much larger than others.", rating: 5, sentiment: "positive" },
  { id: 115, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-03", customerName: "yetanothereviewer", title: "Dogs love them, made in the USA", text: "My dogs are so happy I got these. They're pretty serious chewers, so I love it when I can find good treats for them that last more than five seconds. These are good sized beef hide pieces that keep them busily chewing for several minutes. They love the flavor, too. One of my dogs is a little pickier than the other, but he didn't hesitate when I handed this to him. Both of my dogs grabbed these and ran off like they had just robbed a bank.\n\nI don't often give them beef hide treats because it can upset some dogs' tummies. These pieces aren't as big as a giant rawhide bone, so that helps. Also there's apparently something they do to these that's supposed to make them a little more digestible than regular rawhide. I dunno, but I can tell you that neither of these guys seemed to have any trouble with them.\n\nThese are actually made in the USA, which is one of the first things I look for. I feel like a U.S. manufacturer is less likely to contaminate dog treats with bad things. This company has been making dog treats in a factory in Illinois since 1989, so that's reassuring.\n\nThis is a huge bag of treats for only $18, which seems like a really good deal. The bag is a pound, which may not seem like a lot, but rawhide is pretty lightweight, so it's a big bag. I weighed the bag and it came in at just over 1 lb.", rating: 5, sentiment: "positive" },
  { id: 116, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-03", customerName: "JN", title: "busy time for dogs", text: "The Pet Factory Chip Dips Collagen Chips in Peanut Butter Crunch, our dogs absolutely love the peanut butter flavor and get so excited when it's treat time. These chips are fantastic for keeping our pups busy, as they take a little while to chew through and work on. However, because they are quite rich, we really limit how much they have at one time. We also always make sure to provide them with lots of fresh water afterward.", rating: 4, sentiment: "positive" },
  { id: 117, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-03", customerName: "Amazon Customer", title: "dogs like them", text: "I bought the Pet Factory Chip Dips Collagen Chips in Peanut Butter Crunch for my two dogs, a mix breed and an American Eskimo who both weigh around 30 to 35 pounds. They both like them well enough and will chew one when I offer it, though neither gets as excited as they do with some of their favorite treats. The 16 ounce bag has a solid amount of chips, so the value feels good compared to other options I have tried.\n\nThe smell is milder than a lot of other chews I have bought, which is a nice change. Both dogs finish one in a few minutes and have had no stomach issues or changes in behavior so far. I always supervise them while they chew just to be safe.\n\nI have not noticed any improvements in their coats, joints, or teeth yet, but I have not been using these long enough to really judge that. Overall they are a decent treat that keeps my dogs occupied for a bit without any strong odor, and I will keep buying them since both dogs will eat them without problems.", rating: 5, sentiment: "neutral" },
  { id: 118, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-04", customerName: "Amazon Customer", title: "Peanut butter keeps her busy", text: "My dog really liked the peanut butter flavor and settled right in with one. They're firm enough to last a while but not rock hard, so there's a little flex instead of feeling like a chunk of concrete. My medium-sized dog took a while to finish one, and it didn't upset her stomach afterward. Good value if you have a dog that enjoys chewing. Bag has plenty of treats to last a while.", rating: 4, sentiment: "positive" },
  { id: 119, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-04", customerName: "Amazon Customer", title: "Peanut butter seems to be their favorite flavor", text: "These are one of my dogs most favorite treats - Im sure its because of the flavoring. They actually kind of smell like peanut butter to me as well. They're sized well for my medium sized dog. He chews them until they are gone and has had no digestive issues because of it. My dog isn't really an aggressive chewer so he tends to chew on it for a whilte till it disappears. This bag of treats should last us a while so for the money, they really were a reasonable deal. We'd recommend them to friends and family", rating: 5, sentiment: "positive" },
  { id: 120, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-05", customerName: "Tyler Greene", title: "My Dogs Love Them!!", text: "These turned out to be a much bigger bag than I expected for the price, which was a nice surprise. Plenty of chips in there to last a while, even with more than one dog going after them.\n\nMy dogs are obsessed with these. The peanut butter flavor is clearly a hit and they go straight for the bag whenever it comes out. They seem like a good size for training treats or just an occasional chew, not so big that it becomes a whole ordeal.\n\nGood value for the amount you get and an easy win if your dogs like peanut butter and collagen chews.", rating: 5, sentiment: "positive" },
  { id: 121, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-05", customerName: "Life with Dogs \ud83d\udc3e", title: "Dogs love them", text: "My dogs can be picky about what they eat, but they love these chews!\n\nThey are the perfect size for my medium sized dogs. They are big enough for them to hold between their front paws, but not too big for their smaller mouths.\n\nThey have always been big fans of peanut butter, and they love the taste of these peanut butter flavored chews. One chew can keep them occupied for nearly an hour, so these are great to give them when I need some quiet time.\n\nThis bag of chews is a great value. It's huge, and will last my pups for months.", rating: 5, sentiment: "positive" },
  { id: 122, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-05", customerName: "Tanya", title: "Dogs like them!", text: "My mom's dog loved these treats! The peanut butter flavor was a hit, and they kept him happily occupied for several minutes. I think these are a great value for the size of the bag, and I really appreciate the resealable packaging to help keep them fresh. It's also a big plus that they're made in the USA and contain collagen!\n\nOverall, these are a great treat option that dogs seem to love. I'll definitely keep these on hand as a special chew for my mom's pup.", rating: 5, sentiment: "positive" },
  { id: 123, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-06", customerName: "Amazon Customer", title: "Long-lasting treat that keeps dogs busy with a flavor they love", text: "My dogs absolutely love these chews! They take quite a while to finish just one, which is a huge plus because it keeps them entertained and occupied for a good stretch of time.\n\n\u200bThe Peanut Butter flavor is clearly very savory because my dogs go crazy for them and truly enjoy every bite. It is a great option for heavy chewers who need something to work on.\n\u200b\nThe only downside is that as the chew gets soggy while they work on it, they tend to hold it down with their paws. This leaves the fur on their paws pretty sticky afterward, so you might need to wipe them down when they finish.\n\u200b\nOverall, if you are looking for a long-lasting, flavor-packed treat that keeps your dogs busy, these are definitely worth picking up!", rating: 4, sentiment: "positive" },
  { id: 124, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-06", customerName: "MT2", title: "He was not a fan of the flavor but still took it gratefully", text: "I got these for my neighbor's dog, the same one I always give treats to. He was not a fan of the flavor this time, which surprised me, but he still took it gratefully like he always does. The treats are big, really big sized, so they last a while. Even though he did not seem crazy about the taste, he chewed on it and appreciated it. I might try a different flavor next time. But I appreciate that he is always so polite about accepting whatever I give him. Sweet dog.", rating: 4, sentiment: "neutral" },
  { id: 125, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-07", customerName: "Customer Review", title: "Dog enjoys these for a while but then gets tired of it", text: "I think these are nice quality chews. I love that they\u2019re made in the USA. I think the price is very fair considering how much you get in the bag (it\u2019s hefty). My Welsh Terrier seems to enjoy these but only for a certain amount of time. She is a hard-core chewer so I appreciate these actually take her a while to work on as most treats she is able to chew and eat so quickly. She will work on this for at least 20 to 30 minutes, but then she seems to be over it. I almost wonder if she\u2019s chewing out all of the peanut butter flavor in it and what\u2019s left is just the plain rawhide that isn\u2019t as enjoyable for her. I think these are high-quality and seem very nice, but just beware that your dog might get sick of them especially if they aren\u2019t super crazy chewers.", rating: 4, sentiment: "neutral" },
  { id: 126, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-08", customerName: "Merry Mayhem", title: "My least picky dog was okay with these", text: "I have a GSD rescue, a GSD/Malinois mix rescue, and a senior Samoyed. My senior Samoyed is pretty picky about treats, so I wasn't surprised that she snubbed these. My GSD boy also tends to be picky and not terribly food motivated, and he was also not super excited about these. My GSD/Mal rescue girl accepted them, but wasn't overly enthusiastic. These chips are varied in size and they're pretty thin. My GSD/Mal had no problem chewing them or digesting them. She noses the bag, so clearly they're a hit with her. Because they're coated in the flavor, I was worried about staining on my carpets or my girls bed, but we didn't have any issues with that. She doesn't tend to drop her treats--she just chews and devours, so your mileage may vary on that.\n\nI like that these are made in the USA and do seem to be high quality. I didn't dock a star because my two picky dogs weren't into them, but I think maybe they'd be enticed with a different flavor because it took a few minutes for my dog who is more treat and food motivated to warm up to them.", rating: 4, sentiment: "neutral" },
  { id: 127, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-08", customerName: "Coffee & Feathers", title: "My pups LOVE these peanut butter collagen/rawhide treats!", text: "Both of my large breed pups are aggressive chewers, and they are absolutely obsessed with these! One \u201cchip\u201d keeps them occupied for quite a while, which is impressive with my dogs.\n\nThese are made from beefhide as a source of collagen, so I definitely supervise while my dogs are chewing them. As you can see in my photos, they soften and get thinner as they\u2019re chewed. Once a piece gets small enough that I\u2019m concerned they could swallow it whole, I take it away.\n\nYou get a surprisingly generous amount in the 16 oz bag. At $17.97 at the time of my review, I think these are an excellent value, especially considering how much enjoyment my dogs get out of them. The peanut butter flavor is clearly a hit!\n\nMy Smokey and Charlie Ann LOVE these, and I\u2019ll absolutely buy them again.", rating: 5, sentiment: "positive" },
  { id: 128, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-09", customerName: "spilling the tea", title: "Best for small to medium breeds", text: "These treats passed my dog, Miles, sniff and taste test - he seems to enjoy the peanut butter flavor.\n\nWhile there isn\u2019t a recommended dog size for them, because the chews fit into my palm and are very thin (like chips!) they\u2019re much better suited for smaller dogs or light/ moderate chewers. My large breed dog can finish one in less than 5 minutes and it makes me very nervous that he will choke on a piece. Definitely not long lasting!\n\nWhile the bag is much larger than I expected, it is only filled about 1/3 of the way and the rest is air.", rating: 4, sentiment: "negative" },
  { id: 129, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-10", customerName: "Reviewer", title: "Collagen Dog Chews", text: "These peanut butter collagen chews were an immediate hit with my dog. He loves peanut butter, so I wasn't surprised that he was very interested as soon as I opened the bag.\n\nThe chip-style pieces are a nice size and give him something substantial to chew without committing to a large traditional chew. They last considerably longer than an ordinary treat, and I like being able to easily choose an appropriately sized piece from the bag.\n\nThe 16-ounce bag contains a generous amount, and the pieces have a good texture for chewing. The peanut butter coating definitely seems to make them extra appealing.\n\nAs with any chew, I supervise my dog while he's enjoying one and remove any remaining piece once it becomes small enough that it could potentially be swallowed whole.\n\nOverall, these have been a big hit. They're tasty enough to get my dog's attention while providing a satisfying, longer-lasting chewing experience. \u2b50\u2b50\u2b50\u2b50\u2b50", rating: 5, sentiment: "positive" },
  { id: 130, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-11", customerName: "Celina", title: "My Dog Absolutely Loves These!", text: "My dog goes crazy for these chews! The peanut butter flavor is definitely a favorite, and they keep him busy for quite a while. He\u2019s a pretty strong chewer, so I like finding something that actually holds his attention instead of being gone in five minutes.\n\nI also like that these are easy to digest compared to some other rawhide-style chews. The collagen gives them a nice texture that keeps my dog chewing without being too hard.\n\nThe flavor-dipped coating is a nice bonus because it seems to make them even more exciting for him. As soon as I pull one out, he knows exactly what it is and gets excited.\n\nThese have been a great way to keep my dog occupied and give him something he really enjoys. I\u2019ll definitely be keeping these on hand!", rating: 5, sentiment: "positive" },
  { id: 131, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-13", customerName: "Mac Riddel", title: "High Protein, High Collagen, Massive Bag", text: "Dog treats for our dog are so difficult to review as he'll eat anything! But I can say is that this bag was at least 2x as large as I expected when it arrived. It's huge! And these chips are starting to look a bit too much like real people-food, but Cape Cod Potato Chips these are not. They certainly smell like dog treats and when he hears us open the bag, he shows up out of nowhere to get more. He's only tried the Peanut Butter flavored chips and absolutely loves them. The chips themselves are a bit large as well but do break down easily and we have no worries about them.\n\nWe're also always concerned about providing our dog with a healthy diet and thankfully these seem to hit all the right notes. No extra additives and provides a lot of protein & collagen, yet somehow our particular bag stated it is best buy 7/29 - a solid 3 years away. Though I don't think the contents of this bag will last anything near that long. For the quantity of treats provided, the price is super fair and we're happy with the ingredient list for our Dachshund mix rescue.", rating: 5, sentiment: "positive" },
  { id: 132, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-14", customerName: "Homesteading Mama", title: "Another winner from this brand!", text: "We\u2019ve already tried another collagen chew from this brand, so when I saw the Chip Dips in a different flavor, I already had a pretty good idea my dogs were going to be excited about them and I was right!\n\nThese are a great combination of a durable collagen chew core with a flavorful coating that really seems to keep my dogs interested. They get that satisfying chewing experience they naturally crave, which is especially nice because I love giving my dogs something that provides enrichment instead of just being a treat they gobble down in two seconds. These last our 2 medium sized dogs any 20 minutes.\n\nI also really appreciate that these are collagen-based and high in protein. Knowing they're made in the USA and designed with digestion in mind makes me feel better about giving them as part of our regular treat rotation. The chewing itself is also a nice bonus for helping support healthy teeth and gums while they're enjoying themselves.\n\nAnd apparently, the flavor is a BIG hit in this house. \ud83d\ude02 The dogs definitely don't need any convincing when they see these come out!\n\nWe\u2019ve had a really good experience with this brand so far, and this flavor is another five-star winner for us. If your dog is a serious chewer and you\u2019re looking for something flavorful that also gives them some enrichment, these are definitely worth trying.\n\n\ud83d\udc3e Supplemental Dog Review \u2014 written by the dogs themselves:\n\n\"Dear Amazon customers,\n\n\"We would like to formally report that Mom has been hiding these from us. We do not understand why. We have already proven that we are responsible Chip Dips consumers and feel that one chew every 7-20 minutes would be a perfectly reasonable serving size.\n\n\"The flavor? 10/10. The chewing? Excellent. The part where Mom says 'that's enough'? We give that ONE star.\n\n\"Please send more immediately.\n\nLove,\nThe Dogs \ud83d\udc36\ud83d\udc36", rating: 5, sentiment: "positive" },
  { id: 133, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-17", customerName: "Amazon Customer", title: "Perfect for aggressive chewers", text: "If you have a power chewer at home, you know how hard it is to find treats that last more than a few minutes while still being safe and digestible. These Pet Factory Chip Dips Collagen Chews are an absolute winner.\n\nMy dog is an aggressive chewer and usually destroys traditional chews in record time, but these keep him occupied and happy for much longer. I love that they are made with collagen, which is great for his joints and coat, and the Digest-A-Boost technology gives me peace of mind knowing they are much easier on his stomach than standard rawhide. Plus, he absolutely goes crazy for the peanut butter flavor, it\u2019s clearly a huge hit! They are high quality, long lasting, and finally, a treat that can keep up with him.", rating: 5, sentiment: "positive" },
  { id: 134, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-18", customerName: "WJR526", title: "Great ingredients and even greater taste....per my dog.", text: "I was genuinely surprised by how big this bag is, it's way larger than I expected. Yes, it\u2019s puffed up with air, but even after that settles, there\u2019s still a generous amount of chews inside. As a first time buyer, the ingredient list is what sold me. These are rawhide free, collagen based chews dipped in peanut butter flavoring and boosted with digest\u2011a\u2011boost, which is designed to make them easier on the stomach. That alone made me feel good about trying them.\n\nI have a 12 lb dog, so I assumed the chews would be small. Nope. Even the \u201csmall\u201d ones are about the size of the palm of my hand. The good news is they break cleanly and easily, so we quarter them. Suddenly that 16 oz bag becomes four times more useful for a small dog and still perfectly sized for bigger pups who want a longer chew session. Honestly, that makes these a great value for dogs of all sizes.\n\nMy dog loved these instantly. He guarded his piece like it was a winning lottery ticket. I can\u2019t personally vouch for the taste, but he clearly thinks they\u2019re gourmet. I also appreciate that they\u2019re not sticky, powdery or greasy. No weird residue on my hands, no crumbs everywhere, and no awful smell.....just a mild peanut butter scent.\n\nThey\u2019re easy to digest, long lasting enough to keep a chewer busy, and the price feels fair for the amount you get, especially when breaking them into smaller portions. Overall, I\u2019m really satisfied with these and will happily keep them in our treat rotation.", rating: 5, sentiment: "positive" },
  { id: 135, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-22", customerName: "jwilt8184", title: "Not a Hit for My Picky Dog \u2014 The Texture Was a Dealbreaker", text: "I picked up the Pet Factory Chip Dips Peanut Butter Crunch Rawhide Collagen Dog Chews hoping they\u2019d be a fun, long\u2011lasting treat, especially since they\u2019re made for aggressive chewers and advertised as easy to digest with their Digest\u2011A\u2011Boost\u00ae formula. Unfortunately, my picky dog was not impressed. The chewy, dense texture seemed to be the main issue \u2014 he sniffed them, gave one tentative lick, and then completely refused them. No amount of peanut\u2011butter scent could convince him otherwise.\n\nThe chews themselves feel sturdy and definitely seem built for dogs who love to gnaw, but if your pup is sensitive about textures or prefers softer treats, these might not be the right fit. For dogs who enjoy tougher, flavor\u2011dipped chews, they could be great \u2014 but for mine, they were a miss.", rating: 3, sentiment: "negative" },
  { id: 136, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-08-26", customerName: "Momma Snark", title: "Doggo Approved", text: "Great for an occasional treat. My dog comes running when I pull the bag out.\nGood ingredients and no digestive issue.", rating: 5, sentiment: "positive" },
  { id: 137, asin: "B0H5F7MQ92", itemName: "Chip Dip Peanut Butter", date: "2026-09-03", customerName: "Stephen", title: "These are a great value for the money - my picky dogs love them", text: "I started with the flavor bomb pack. Turns out their favorite flavor is peanut butter. Good snack for my dogs. It occupies them for 5-10 minutes which is nice. Also you get a lot of pieces in the bag \u2014 it is a good value relative to a lot of other expensive dog treats.", rating: 5, sentiment: "positive" },
  { id: 138, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-09", customerName: "Amazon Customer", title: "Chicken and Catnip: A Love Story My Cat Didn't Join", text: "I got these SmartyKat freeze-dried chicken and catnip treats because the two-ingredient formula sounded good, with just real chicken and catnip. The little crunchy cubes are also a convenient size for treating. Unfortunately, my cat wasn\u2019t very interested. She sniffed them a few times and mostly walked away, even when I sprinkled some over her regular food. I liked the simple ingredient list and the fact that they\u2019re easy to give, but the flavor just didn\u2019t appeal to my picky cat. They may work better for other cats, but mine wasn\u2019t impressed.", rating: 4, sentiment: "negative" },
  { id: 139, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-11", customerName: "Gillian", title: "Lukewarm reception from my furry overlord", text: "Chicken and catnip are my little guys' favorite flavors. I thought these treats would be an immediate hit for that reason, but it took him longer than expected to give these a try. He's a little wary of anything new and doesn't eat a lot of freeze dried treats, apart from the lolipop style ones. That said, he will go absolutely ham on licking the catnip and chicken flavored lolipops. I offered four of these SmartyKat treats, and it took much cajoling to get him to try the first one. The fourth one, he just batted around a bit before leaving it alone.\n\nAt the end of the day, my cat is the reviewer - I'm just his proxy (and faithful servant). I would guess he only gives this treat 3 toe beans. Didn't totally turn his nose up at them, but they also didn't exactly blow his fur back.", rating: 3, sentiment: "neutral" },
  { id: 140, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-11", customerName: "MJS", title: "My cats LOVE these treats!", text: "Yep... My cats go absolutely bonkers for these treats. These little freeze-dried chicken and catnip cubes are the perfect size for tossing a few their way in the middle of the day. Apparently the combination is irresistible because I have three very attentive kitties suddenly appearing whenever I open the bag.\n\nThey have a nice crunchy texture, don't make a mess at all, and the real chicken makes me feel better about what I'm handing out as bribes. The cats have spoken, and apparently these are five-star accommodations. Definitely recommended!", rating: 5, sentiment: "positive" },
  { id: 141, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-12", customerName: "Gabriella", title: "Kitties Think NO. Dogs Think YES!", text: "I am always on the lookout for fun, healthy treats for our cats, but for our elderly kitty especially as she heads deeper into her geriatric years.\n\nI was excited for these, thinking that they would be a mega hit, especially being just 2 ingredients (chicken & catnip) and being from a brand that our cats love.\n\nUnfortunately... all of the cats didn't really like these. Lily (16 yo) smelled them and acted disgusted. Dante (6) smelled these, and smelled them, smelled, smelled some more, smelled a different side, ate one slowly, smelled again and decided he didn't like them. Rosey (10ish) ate two right away, apparently got a whiff of them while eating, then refused to eat more. Tom (10ish) had no interest whatsoever.\n\nI was bummed, but I didn't want these to go to waste, so looked up if dogs could eat catnip, and apparently they can. It can produce a calming effect, so I thought I'd see if they liked them. Both 100% think they are great, so now these are dog treats.\n\nThere isn't any serving information, so maybe only give a few out at a time, regardless of cat or dog.\n\nWhile these weren't a hit with any of our cats, they were with our dogs, so are still a win.", rating: 4, sentiment: "negative" },
  { id: 142, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-12", customerName: "Customer Review", title: "Great treats, a hit with our cat that understands how those work", text: "We have two cats, one of which has failed to figure out how any treats work, despite having watched our black cat eat them for years and years now. These are no exception sadly, he licked them once, but then went to bat them like a toy before ignoring it. Breaking it apart didn't work either to pique his interest.\n\nHowever, our other cat who has no issue understanding treats loves these! He was trying to stick his head in the bag as soon as I opened it. The cubes are a great size and I love that these are just chicken breast and catnip, nothing weird or funky. He happily eats these out of my hand or if placed out somewhere. They're easy enough to break apart with your fingers if your cat needs a bit smaller, although it does get a bit crumbly. The zippered pouch works well for resealing the bag and the top tore off easily without needing scissors.", rating: 5, sentiment: "neutral" },
  { id: 143, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-12", customerName: "PNW FAM", title: "Kitty goes crazy for them! Good quality!", text: "These treats were a hit with my cats. They have a nice crunchy texture and the combination of real freeze-dried chicken and catnip makes them especially appealing. I like that they\u2019re small enough to use as a quick treat without making a big mess. They\u2019re easy to keep on hand for rewards or just an occasional snack. Definitely a treat I\u2019ll keep buying.", rating: 5, sentiment: "positive" },
  { id: 144, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-12", customerName: "Amazon Customer", title: "Simple treats that my cats love", text: "My cats are excited about these SmartyKat Freeze Dried Real Chicken & Catnip Crunchy Cube Treats and gather around as soon as I open the pouch. They have a crispy freeze-dried texture and I appreciate them being just two simple ingredients: chicken and catnip. The cubes vary a little in size, but are similar to adult-sized kibble. We have kittens right now, and they love this as much as my adult cats. With the pure ingredients, it's a treat I feel great about feeding them all, and the pouch conveniently reseals.", rating: 5, sentiment: "positive" },
  { id: 145, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-13", customerName: "Amazon Customer", title: "Cat likes it", text: "My senior cat is quite picky, and I never know how she will take to new food. She likes freeze-dried chicken and catnip, so I thought I would get her these cubes and see if she eats them or not.\n\nCompared to other freeze-dried chicken products I have bought, you can\u2019t see the meat fiber when you crumble these cubes. It seems more like both the chicken and the catnip were pulverized and then pressed into form. This makes them slightly harder than other freeze-dried, single-ingredient products I had before. Since the catnip and the chicken are the only ingredients, the texture difference and taste seem to be ok for her.\n\nOut of curiosity, I served my cat these cubes slightly crumbled up on a plate with some other freeze-dried meats and separated them to see if she would eat all of them. To my surprise, she went for these cubes first before she ate the other freeze-dried chicken and duck. I was delighted, since most of the time she refuses to eat new products. I have since given her these cubes several times, and she always eats these first.\n\nSo, for a change, this product is actually a winner with my cat, and if it remains so, I will repurchase it.", rating: 5, sentiment: "positive" },
  { id: 146, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-13", customerName: "Amazon Customer", title: "welp. They like 'em.", text: "Im familiar with SmartyKat. I have many of their toys, and even gotten their nip a few times.\nThis is the first Ive seen of food/treats, though. Im often iffy about new food for my cats, but there's just the two ingredients and SmartyKat is a known name, so...\nI grabbed a few from the bag, hid them in my hand, and wandered over to where Cat One was chilling. She immediately knew something was up, sniffing the air and approaching me as soon as I sat down, searching for the source of the mysterious smell, headbutting my hand when she found it and scarffed them down as soon as I let her, and she was eager for more. Cat Two was slightly more reserved in his first inspection, but quickly decided he liked them and was practically reaching for my hand for the last of the treats I offered him.\nI think this one's a pass.", rating: 5, sentiment: "positive" },
  { id: 147, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-14", customerName: "Amazon Customer", title: "Good treats with sound ingredients", text: "I have to say that cats are weird. If you have cats you know what fickle little turds they can be. These are a hit for some, not for others, and some will act like they are rancid flesh. The ingredients are sound and some cats really dig it but YMMV. The bag isn't huge, and some cats will later dig them but upon first offering them, some cats will be turds about it and refuse. For giggles I took to work where we have lots of ferel and abandoned cats and needless to say half of them went bonkers and others were skeptical. All in all, get a small bag and they may be a hit. If your cats refuse them, its not the treats, your cat is indeed a turd.", rating: 5, sentiment: "neutral" },
  { id: 148, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-14", customerName: "Amazon Customer", title: "Cat Eats Them, But It's Not A Huge Favorite", text: "Unlike more solid cat treats, these freeze dried cat treats are much lighter, and don't seem to have as much odor as other treats do. If you can smell them, they have a mild chicken scent that is not unpleasant. The problem with freeze-dried, of course, is that being so light and stiff, they do tend to fracture and break into lots of tiny pieces, which is the case with both human freeze-dried candy that I have tried, and these treats. My cat initially seemed excited at the shaking of the treat bag, but when presented with these treats, just walks away. If I put them in her dish, however, I come back later to find every single one of them gone. So, I think she likes them, but not in a climbing-my-leg-to-get-them way. I would not call them an \"enticement,\" in other words. But, they will be eaten, and they seem quality, so no major complaints.", rating: 4, sentiment: "neutral" },
  { id: 149, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-14", customerName: "Amazon Customer", title: "Huge hit with all 3 cats, even ones that don't like catnip; it is a product of China, but very fresh", text: "Big hit with 3/3 cats here, from 6 to 21 years old! I think they\u2019re more interested in the chicken than the catnip as only one of my cats is \u201cactivated\u201d by catnip or cares about it, and this didn\u2019t make her roll around or anything.\n\nThe consistency reminds me of croutons and they\u2019re also all evenly cubed. For regular cats they\u2019re a perfect size, but since two of mine are smoosh faces I like to break the treats up a bit. This is really easy to do though it does crumble somewhat.\n\nSince it\u2019s not obvious from the listing, I do want to mention it\u2019s a product of China. It does seem high quality and fresh though, and hasn\u2019t upset our kitties\u2019 tummies. None of the pieces are greasy or sharp, which I\u2019ve encountered with freeze-fried chicken treats occasionally.\n\nOverall my cats love these and I like the minimal ingredients, so I\u2019d get these for them again.", rating: 5, sentiment: "positive" },
  { id: 150, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-15", customerName: "Microcap", title: "My cats approve so I approve as well! Two ingredients, just catnip and chicken! Clean and healthy!", text: "A treat my cat loves!\n\nMy cat is very picky with treats. It's either he likes it or he doesn't and there's no real way of knowing before you purchase it. Despite the ingredients being similar, there are times where he will just nibble at it and then spit it out or just leave it on his tray and never touch it again.\n\nWe've gone through dozens of treats to find some that he enjoys and quite frankly, it's been a huge hassle having to sort through them!\n\nThankfully, these treats are treats he enjoys eating and actively begs to have. He knows I store it in a cabinet near his cat stuff and constantly paws and meows for me to give him some treats!\n\nThese treats are cubed-shaped and is ideal for all sizes of cats. It's small but also pretty uniformed in shape so it goes well when I mix a couple of them with his dry cat food.\n\nThere are only two ingredients: Catnip and chicken. So no artificial flavor, fillers, corn meal, etc., that end up being bad for your cat long-term if they consume a lot of it.\n\nThese are more suited for giving to your cats to teach them tricks or commands. I've been using them to add to his dry food just to spice things up a bit but I would not recommend overfeeding your cat with these or they may be more selective with what they choose to eat knowing that you are constantly going to give them cat treats.\n\nOverall, I recommend these cat treats. They are healthy, clean ingredients, and my cats like them so I approve!", rating: 5, sentiment: "positive" },
  { id: 151, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-15", customerName: "Amazon Shopper", title: "Apparently This Is Cat Crack", text: "I am not even exaggerating when I say our cats are obsessed with these. We have Loki, our older cat, and Sadie, our little kitten, and these have somehow become the feline equivalent of an addictive substance in our house. The second they realize the bag is coming out, suddenly both cats are very attentive and apparently have absolutely nothing else going on in their lives.\nThe freeze-dried chicken pieces have a nice crunchy texture, and the combination of real chicken and catnip is clearly doing something right because even our cats with very different personalities agree that these are worth showing up for. I like that they're small enough to use as treats without handing them an enormous snack every time. They also work nicely as a little reward during play or when I need to convince one of them that whatever I'm asking them to do is actually their idea.\nThese have become a very successful addition to our treat rotation. The quality seems good, and the cats' reaction is about as strong an endorsement as I can get without putting a tiny microphone in front of them. If your cat is a fan of chicken or catnip, I would expect these to disappear quickly.", rating: 5, sentiment: "positive" },
  { id: 152, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-16", customerName: "CS", title: "SmartyKat Freeze Dried Real Chicken & Catnip Crunchy Cube Treats", text: "My cat, Newspaper, absolutely loves these SmartyKat Freeze Dried Real Chicken & Catnip Crunchy Cube Treats. He has never really been a treat-loving cat, so I was genuinely surprised by how much he enjoys these. The moment I give him a few, he eagerly crunches them up, and it's honestly pretty cute to watch. He even shakes his head while he's eating them, almost like he's so excited he can't contain himself. Since he is usually indifferent to treats, that reaction says a lot. I also appreciate that these treats are made with real chicken and catnip, and at $9.99 a bag they are very reasonably priced. It's nice to be able to give him something he truly enjoys without spending a fortune. If my picky cat approves, that's a pretty strong endorsement in my book.", rating: 5, sentiment: "positive" },
  { id: 153, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-16", customerName: "Mom next door", title: "My cats went crazy for these", text: "These were a hit with my cats. They love chicken already, but adding catnip definitely made these more exciting for them. The little freeze-dried cubes are crunchy and easy to give as a quick treat.\n\nI also really like that the ingredient list is so simple: chicken and catnip. No giant list of fillers or things I can\u2019t pronounce. I can give them a few straight from the bag or crumble some over their food.\n\nIf your cat is a chicken lover, these are definitely worth trying.", rating: 5, sentiment: "positive" },
  { id: 154, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-17", customerName: "Cara", title: "Two of Shaggy's Favorites - Chicken and Catnip", text: "These are small freeze-dried chicken cubes, similar to another chicken treat I already give my cat. The SmartyKat brand adds catnip, so it combines two of Shaggy\u2019s favorites in one little treat! I also like that they\u2019re small and bite-sized for my senior cat. I\u2019m always looking for healthy snacks for my kitties, and these are a great option. Shaggy gobbled them up quickly and clearly enjoyed them. He\u2019s always looking for something to eat, so I like giving him a few of these between meals to help tide him over. Definitely another favorite in our house!", rating: 5, sentiment: "positive" },
  { id: 155, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-20", customerName: "Michael", title: "Mixed Results with these Treats", text: "These freeze dried chicken treats are a hit or miss with my cats, and it seems the flavor preference is quite personal. One cat loves them, while the other will chew it for a second before dropping it and looking at me like \"where's the real treat?\". The quality is good, and the crunchy texture is appreciated. However, the mess factor is something to consider, especially if you have a cat who loves to chew and explore. Overall, if you have a cat who loves chicken and catnip, these treats are worth trying. Just be prepared for potential rejection from cats with particularly discerning palates.", rating: 4, sentiment: "neutral" },
  { id: 156, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-20", customerName: "v", title: "Two out of three cats approve", text: "SmartyKat Freeze Dried Real Chicken & Catnip treats really got my kitties' attention. When I open the bag, they swarm like sharks looking for a treat. One of my kitties could not get enough, while another just sniffed it. She was excited about the smell but had no interest in actually eating it. Third one liked it just as much as my big boy.\n\nThe treats are little solid puffed squares, which gives them a different texture and appearance from other treats they have had. They have a nice smell, and two out of three enjoyed them. At the time of my review, they are $9.99 for a 2.8 oz bag, which I think is pretty pricey compared to other name brand treats my kitties love. When these go on sale my kitties will be happy for me to get more.", rating: 4, sentiment: "neutral" },
  { id: 157, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-21", customerName: "Ren", title: "Sniffing and licking the bag", text: "These treats were an absolute HIT. My girl was sniffing, licking, and biting the bag before I could even give them to her. I mean, what other endorsement of them could I want? I have to only give them a couple at a time, as I am sure she would gorge herself on the entire bag if I would let her.\n\nI am not personally an ingredients snob, but if you are, I would also recommend these to you. They are a good source of whole food protein and are made well. Freeze dried treats tend to be the best in terms of ingredients when looking for whole foods for pets.\n\nIn terms of value, $9.99 for this size a bag is and okay value. Whole ingredients typically cost more.", rating: 5, sentiment: "positive" },
  { id: 158, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-22", customerName: "Paul David Williams Jr", title: "Cat Crack", text: "Our cat demands these, she's totally addicted\n", rating: 5, sentiment: "positive" },
  { id: 159, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-22", customerName: "vkb", title: "A perfect, healthy treat so, of course, my cat won\u2019t touch them", text: "It was a promising start. I carry the bag into the room, cat rushes over, jumps on my lap, head butting, smelling bag, rubbing bag, rubbing licking hand, can\u2019t get the bag open fast enough. Stop. He looks at me as if I had tempted him with the most gorgeously wrapped gift but inside was just something inedible. He won\u2019t touch these treats.\n\nI really, really, really wanted him to like these because treats because they have just two ingredients! Just chicken and catnip! So they are 75% protein with just a little fat and fiber. The treats are little cubes of a size that generally appeals to cats. They\u2019re very light with almost a styrofoam texture. They\u2019re the color of cooked chicken and are speckled with tiny catnip bits. I don\u2019t especially like the smell; it\u2019s just a pet food smell that I don\u2019t find pleasant. The zip lock will help keep them fresh but they won\u2019t last long if your cat likes them. Note that they don\u2019t have to be refrigerated.\n\nThe product is not the problem. I was able to test their appeal by offering them to my sister\u2019s cat. She LOVES them and would\u2019ve followed me out the door but I left the bag there for her. I\u2019m familiar with the fussiness of cats so my rating is always based on the quality of the food, not my cat\u2019s reaction to it. I consider these a perfect, healthy cat treat that rates a high 5 in my book. The price is good value, comparable in price to the treats I normally buy and a good deal compared to freeze-dried treats I\u2019ve tried in the past.", rating: 5, sentiment: "neutral" },
  { id: 160, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-23", customerName: "Coffee & Feathers", title: "Easy to break apart for senior kitties - a hit with my cat!", text: "My senior kitty loves these! She has some age-related tooth loss, so she is a little hesitant to eat the cubes whole. Thankfully, they\u2019re very light and airy, and one quick pinch breaks them apart into smaller pieces. Once I do that, she gobbles them right up.\n\nShe\u2019s had no stomach issues from these treats, and she definitely seems to enjoy the flavor. I also really like that they\u2019re made with only two ingredients: chicken breast and catnip.\n\nFor under $10 at the time of this review, I think these are a good value for a quality freeze-dried treat with such a simple ingredient list. I\u2019ll happily keep these on hand for her.", rating: 5, sentiment: "positive" },
  { id: 161, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-27", customerName: "Reviews", title: "Unfortunately my cat did not like them", text: "OK, so I have to say upfront that my cat is super picky when it comes to food and treats. So it was not a total surprise when he turned his nose up at these. The treats come in a resealable bag, which helps keep them fresh. The treats are small cubes, and the texture is crunchy. They do have a smell to them, but it's not too overpowering or unpleasant. The only 2 ingredients listed on the bag are chicken breast and catnip, so they are not full of filler or anything artificial. Price-wise, $10 is a fair price as long as your cat likes them.\n", rating: 4, sentiment: "negative" },
  { id: 162, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-08-29", customerName: "Quality Product Reviews!", title: "Ignored by My Cats, but a Hit with the Yard Bees", text: "I picked up these freeze-dried chicken and catnip treats hoping for a simple, natural two-ingredient snack for my cats, but it turned out to be a complete miss in our household. The crunchy cubes look decent in the bag and have a noticeable herbal aroma from the catnip infusion, but both of my cats were completely uninterested in these treats. Neither one even licked the treats when offered by hand or placed in their bowls; they just gave them a quick sniff and walked away. Rather than letting the rest of the bag go to waste, I ended up tossing them outside for the outdoor animals, and surprisingly, the bees in my yard loved them and immediately swarmed the crumbs. While the clean ingredient list sounds great on paper, it does not do much good when the intended audience refuses to touch them.\n", rating: 1, sentiment: "negative" },
  { id: 163, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-09-01", customerName: "Michelle Nogales", title: "Maybe these are fine? My cat won't touch them.", text: "Maybe these are fine? My cat won't touch them.", rating: 3, sentiment: "negative" },
  { id: 164, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-09-03", customerName: "Stephen", title: "Cats and dogs both like these treats.", text: "My friend\u2019s cats loved these. And my dogs tried to eat them too.", rating: 3, sentiment: "positive" },
  { id: 165, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-09-03", customerName: "Johneric8", title: "\ud83d\udc14\ud83c\udf3f\ud83d\udc31 TWO INGREDIENTS, ZERO CAT COMPLAINTS", text: "My favorite thing about these treats is how ridiculously simple the ingredient list is: real chicken and catnip. That's it. No long chemistry project printed on the back of the bag, just two ingredients that cats seem to understand immediately.\n\nThe freeze dried chicken has a nice crunchy texture and plenty of natural meat aroma. The little cubes are easy to portion out as treats, rewards or just because your cat has decided that you are late with dinner.\n\nThe addition of catnip makes these particularly entertaining. They can be given straight from the bag or crumbled over regular food as a little flavor boost. I also like using small pieces for bonding and positive reinforcement.\n\nThe cubes are small enough that you can control portions easily, and the freeze dried format makes them convenient to store and handle without the mess of traditional wet treats.\n\nIf you're looking for a treat with a short, recognizable ingredient list, this one is hard to argue with. Real chicken plus catnip is about as straightforward as cat treats get.\n\nTwo ingredients. Freeze dried chicken. Catnip. Apparently, someone finally asked the cats to write the recipe. \ud83d\ude39", rating: 5, sentiment: "positive" },
  { id: 166, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-09-07", customerName: "Autumn Caraluzzi", title: "As promised, it\u2019s excellent", text: "Very happy with the product!! Cats love it!", rating: 5, sentiment: "positive" },
  { id: 167, asin: "B0H5FQ2ZPZ", itemName: "SMK Freeze Dried Treat", date: "2026-09-08", customerName: "Kyra", title: "A tasty treat that my cats really enjoy", text: "My cats were very interested in these treats as soon as I opened the bag. The combination of real freeze dried chicken and catnip seems to be a big hit, and they have a nice crunchy texture that makes them different from some of the softer treats we usually give them. The cubes are a convenient size for treating without having to break anything apart, and they are easy to grab when I want to give the cats a little reward.\n\nI also like that real chicken is the main ingredient because I prefer giving my cats treats that have an ingredient list I can feel good about. The freeze dried texture makes them lightweight and easy to store, and the 2.8 ounce bag gives me plenty to keep around for treat time. They have also been useful for getting the cats' attention when I need them to come over.\n\nWith multiple cats, I wish the bag were a little larger because it goes faster than I would like when everyone wants a treat.\n\nThese have been a tasty addition to our treat rotation. The cats enjoy them, the chicken flavor is appealing, and the added catnip makes them especially interesting. They are definitely worth keeping around for cats that enjoy crunchy treats.", rating: 4, sentiment: "positive" },
];

